window.USUL={"tracks":{"usul":{"ic":"⚖️","t":"أصول الفقه","d":"القواعد التي يستنبط بها العلماء الأحكام من الأدلة. على ترتيب «الورقات» للجويني، ثم «روضة الناظر» و«الموافقات».","lessons":[{"id":"tarif","t":"ما أصول الفقه؟","idea":"الفقه: معرفة الأحكام الشرعية العملية من أدلتها التفصيلية. وأصول الفقه: معرفة الأدلة الإجمالية وكيفية الاستفادة منها، وحال المستفيد (المجتهد). فالفقيه يقول: الصلاة واجبة، والأصولي يقول: لماذا؟ لأن الأمر يفيد الوجوب.","rules":["ثمرته: معرفة كيف يُستنبط الحكم، وفهم سبب اختلاف العلماء.","أول من صنّف فيه الإمام الشافعي في «الرسالة»."],"ex":[["﴿وأقيموا الصلاة﴾","الفقيه: الصلاة واجبة. الأصولي: صيغة «افعل» تدل على الوجوب ما لم تصرفها قرينة."]],"q":[["أول من صنّف في أصول الفقه:",["أبو حنيفة","الشافعي","ابن حزم"],1,"في كتابه «الرسالة»."]],"r":[["waraqat:2","الورقات في أصول الفقه","معنى أصول الفقه"],["risala-shafii:1","الرسالة","مقدمة"]],"s":[]},{"id":"hukm","t":"الحكم الشرعي التكليفي","idea":"أفعال المكلفين كلها لا تخرج عن خمسة أحكام: الواجب، والمندوب، والمباح، والمكروه، والمحرم.","rules":["الواجب: يُثاب فاعله ويُعاقب تاركه (الصلوات الخمس).","المندوب (المستحب): يُثاب فاعله ولا يُعاقب تاركه (السنن الرواتب).","المباح: لا ثواب ولا عقاب في ذاته (الأكل من الطيبات)، ويؤجر عليه بالنية الصالحة.","المكروه: يُثاب تاركه امتثالاً ولا يُعاقب فاعله.","المحرم: يُثاب تاركه امتثالاً ويُعاقب فاعله (الربا)."],"ex":[["﴿وأحلّ الله البيع وحرّم الربا﴾","البيع مباح، والربا محرم."]],"q":[["ما يُثاب فاعله ولا يُعاقب تاركه:",["الواجب","المندوب","المباح"],1,""],["كم الأحكام التكليفية؟",["ثلاثة","خمسة","سبعة"],1,""]],"r":[["waraqat:3","الورقات في أصول الفقه","أنواع الحكم"],["rawdat-nazir:108","روضة الناظر وجنة المناظر","معنى الحكم"]],"s":[]},{"id":"wadi","t":"الحكم الوضعي","idea":"هو ما وضعه الشرع علامة على الحكم: كالسبب والشرط والمانع والصحة والفساد.","rules":["السبب: ما يلزم من وجوده الوجود ومن عدمه العدم (زوال الشمس سبب لوجوب الظهر).","الشرط: ما يلزم من عدمه العدم ولا يلزم من وجوده الوجود (الطهارة شرط للصلاة).","المانع: ما يلزم من وجوده العدم (الحيض مانع من الصلاة).","الصحيح: ما ترتبت عليه آثاره، والفاسد: ما لم تترتب عليه."],"ex":[["﴿أقم الصلاة لدلوك الشمس﴾","دلوك الشمس سبب لوجوب الصلاة."]],"q":[["الطهارة بالنسبة للصلاة:",["سبب","شرط","مانع"],1,""]],"r":[["waraqat:3","الورقات في أصول الفقه","أنواع الحكم — …حظور والمكروه والصحيح والباطل فالواجب ما يثاب علي …"],["rawdat-nazir:128","روضة الناظر وجنة المناظر","فصل: [في الشرط وأقسامه"]],"s":[]},{"id":"adilla","t":"الأدلة المتفق عليها","idea":"الأدلة التي اتفق عليها جمهور العلماء أربعة: القرآن، والسنة، والإجماع، والقياس. وهي مرتبة في القوة هكذا.","rules":["القرآن: كلام الله المنزل على محمد ﷺ، المتعبد بتلاوته.","السنة: ما صدر عن النبي ﷺ من قول أو فعل أو تقرير.","الإجماع: اتفاق مجتهدي الأمة بعد وفاة النبي ﷺ على حكم شرعي.","القياس: إلحاق فرع بأصل في الحكم لعلة جامعة بينهما (تحريم المخدرات قياساً على الخمر بعلة الإسكار).","أدلة مختلف فيها: الاستحسان، والمصالح المرسلة، وقول الصحابي، وشرع من قبلنا، والاستصحاب، والعرف."],"ex":[["﴿فإن تنازعتم في شيء فردّوه إلى الله والرسول﴾","الرد إلى الكتاب والسنة."]],"q":[["تحريم المخدرات قياساً على الخمر: العلة:",["الإسكار","السيولة","اللون"],0,""]],"r":[["waraqat:17","الورقات في أصول الفقه","9- الإجماع — وإما"],["waraqat:21","الورقات في أصول الفقه","11- القياس — وأما"],["rawdat-nazir:103","روضة الناظر وجنة المناظر","فصل: [في أسباب مخالفة البرهان أو القياس"]],"s":[]},{"id":"amr","t":"الأمر والنهي","idea":"الأمر: طلب الفعل على وجه الاستعلاء، وصيغته «افعل». والنهي: طلب الترك، وصيغته «لا تفعل». ودلالتهما الأصلية: الوجوب والتحريم، إلا بقرينة.","rules":["الأمر المطلق يقتضي الوجوب عند الجمهور، وقد يُصرف إلى الندب بقرينة: ﴿فكاتبوهم إن علمتم فيهم خيراً﴾.","النهي يقتضي التحريم، وقد يُصرف إلى الكراهة بقرينة.","الأمر بعد الحظر يعيد الحكم إلى ما كان قبله: ﴿وإذا حللتم فاصطادوا﴾ (الإباحة)."],"ex":[["﴿وإذا حللتم فاصطادوا﴾","أمر بعد حظر، فأفاد الإباحة لا الوجوب."]],"q":[["الأصل في الأمر المجرد عن القرائن:",["الإباحة","الوجوب","الندب"],1,"عند الجمهور."]],"r":[["waraqat:8","الورقات في أصول الفقه","2- الأمر — والأمر استدعاء الفعل بالقول ممن هو دونه على سبيل الوجوب — و"],["waraqat:10","الورقات في أصول الفقه","3 - النهي"]],"s":[]},{"id":"amm","t":"العام والخاص، والمطلق والمقيد","idea":"العام: لفظ يشمل أفراداً كثيرة دفعة واحدة (المسلمون). والخاص: ما يُخرج بعض أفراد العام. والمطلق: لفظ شائع في جنسه (رقبة)، والمقيد: ما قُيّد بوصف (رقبة مؤمنة).","rules":["من صيغ العموم: «كل»، و«جميع»، والجمع المعرف بأل، والنكرة في سياق النفي.","التخصيص بالاستثناء والشرط والصفة، وبدليل منفصل.","يُحمل المطلق على المقيد إذا اتحد الحكم والسبب."],"ex":[["﴿والمطلقات يتربصن بأنفسهن ثلاثة قروء﴾","عام في المطلقات، وخُصّ بالحامل: ﴿وأولات الأحمال أجلهن أن يضعن حملهن﴾."]],"q":[["«رقبة مؤمنة»:",["مطلق","مقيد"],1,""],["النكرة في سياق النفي تفيد:",["الخصوص","العموم"],1,""]],"r":[["waraqat:11","الورقات في أصول الفقه","4 - العام والخاص"],["waraqat:11","الورقات في أصول الفقه","4 - العام والخاص"],["rawdat-nazir:226","روضة الناظر وجنة المناظر","فصل: [في ألفاظ العموم"]],"s":[]},{"id":"naskh","t":"الناسخ والمنسوخ","idea":"النسخ: رفع حكم شرعي متقدم بدليل شرعي متأخر. وهو من حكمة الله في التدرج بالتشريع.","rules":["لا يثبت النسخ بالاحتمال، بل بنص أو بمعرفة التاريخ مع تعذّر الجمع.","إذا أمكن الجمع بين الدليلين قُدّم على القول بالنسخ.","من أمثلته: تحويل القبلة من بيت المقدس إلى الكعبة."],"ex":[["﴿قد نرى تقلّب وجهك في السماء فلنولينك قبلة ترضاها﴾","نسخ استقبال بيت المقدس."]],"q":[["إذا أمكن الجمع بين دليلين:",["يُقال بالنسخ","يُجمع بينهما"],1,""]],"r":[["waraqat:15","الورقات في أصول الفقه","8- النسخ — وأما"],["nasikh-nahhas:1","الناسخ والمنسوخ","باب الترغيب في تعلم الناسخ والمنسوخ"]],"s":[]},{"id":"ijtihad","t":"الاجتهاد والتقليد والفتوى","idea":"الاجتهاد: بذل الوسع في استنباط الحكم الشرعي من دليله، ولا يكون إلا ممن جمع أدواته. والتقليد: قبول قول المجتهد بلا معرفة دليله، وهو فرض العامي.","rules":["شروط المجتهد: معرفة الكتاب والسنة ومواضع الإجماع، والعربية، وأصول الفقه، والناسخ والمنسوخ.","العامي يسأل أهل العلم الموثوقين: ﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾.","المجتهد إن أصاب فله أجران، وإن أخطأ فله أجر."],"ex":[["﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾","واجب من لا يعلم: السؤال."]],"q":[["المجتهد إذا أخطأ:",["يأثم","له أجر واحد"],1,"كما في الحديث المتفق عليه."]],"r":[["waraqat:29","الورقات في أصول الفقه","16- الاجتهاد — وأما"],["waraqat:28","الورقات في أصول الفقه","شروط المستفتي — …ان يكون من اهل التقليد وليس للعالم ان يقلد والتقلي…"]],"s":[]},{"id":"maqasid","t":"مقاصد الشريعة","idea":"جاءت الشريعة لتحقيق مصالح العباد ودفع المفاسد عنهم، ومقاصدها الضرورية خمس: حفظ الدين، والنفس، والعقل، والنسل (العرض)، والمال.","rules":["الضروريات: ما لا تقوم الحياة إلا بها، والحاجيات: ما يرفع الحرج، والتحسينات: مكارم الأخلاق ومحاسن العادات.","من قواعدها: المشقة تجلب التيسير، والضرر يزال، ودرء المفاسد مقدم على جلب المصالح."],"ex":[["﴿يريد الله بكم اليسر ولا يريد بكم العسر﴾","من مقاصد الشريعة: رفع الحرج."]],"q":[["تحريم الخمر يحفظ:",["المال","العقل","النسل"],1,""]],"r":[["muwafaqat:20","الموافقات","5- دعوته الجادة إلى التطبيق العملي بمزج الفروع الفقهية بالمقاصد الشرعي"]],"s":[]}]},"mustalah":{"ic":"📜","t":"مصطلح الحديث","d":"كيف عرف العلماء الصحيح من الضعيف؟ على ترتيب «نخبة الفكر» وشرحها «نزهة النظر» لابن حجر، و«مقدمة ابن الصلاح».","lessons":[{"id":"tarif","t":"السند والمتن","idea":"كل حديث له جزآن: السند (سلسلة الرواة الذين نقلوه)، والمتن (نص الكلام المنقول). وعلم المصطلح يدرس أحوال السند والمتن ليُعرف المقبول من المردود.","rules":["مثال: حدثنا الحميدي، قال: حدثنا سفيان... عن عمر بن الخطاب: «إنما الأعمال بالنيات». فالرواة هم السند، والقول هو المتن.","قال ابن المبارك: الإسناد من الدين، ولولا الإسناد لقال من شاء ما شاء."],"ex":[["«إنما الأعمال بالنيات»","متن أول حديث في صحيح البخاري."]],"q":[["سلسلة الرواة تسمى:",["المتن","السند"],1,""]],"r":[["nukhba:3","نخبة الفكر في مصطلح أهل الأثر","مقدمة"],["nuzhat-nazar:1","نزهة النظر في توضيح نخبة الفكر","مقدمة"]],"s":[]},{"id":"mutawatir","t":"المتواتر والآحاد","idea":"الخبر من حيث عدد رواته: متواتر يرويه جمع كثير يستحيل تواطؤهم على الكذب في كل طبقة، وآحاد: ما لم يبلغ ذلك.","rules":["المتواتر يفيد العلم القطعي، مثل: «من كذب عليّ متعمداً فليتبوأ مقعده من النار».","الآحاد ثلاثة: المشهور (ثلاثة فأكثر في كل طبقة)، والعزيز (اثنان)، والغريب (واحد).","الآحاد الصحيح حجة يجب العمل به في العقائد والأحكام عند أهل السنة."],"ex":[["«إنما الأعمال بالنيات»","حديث غريب في أوله: تفرد به عمر، ثم علقمة، ثم محمد بن إبراهيم، ثم يحيى بن سعيد، ثم اشتهر."]],"q":[["الحديث الذي يرويه راوٍ واحد في إحدى طبقاته:",["المشهور","العزيز","الغريب"],2,""]],"r":[["nukhba:4","نخبة الفكر في مصطلح أهل الأثر","الخبر إما أن يكون له"],["nuzhat-nazar:62","نزهة النظر في توضيح نخبة الفكر","تعريف المتواتر"]],"s":[]},{"id":"sahih","t":"الحديث الصحيح","idea":"الصحيح: ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه، من غير شذوذ ولا علة.","rules":["شروطه خمسة: اتصال السند، وعدالة الرواة، وضبطهم، وعدم الشذوذ (مخالفة الثقة لمن هو أوثق)، وعدم العلة القادحة.","أصح الكتب بعد كتاب الله: صحيح البخاري ثم صحيح مسلم.","المتفق عليه: ما رواه البخاري ومسلم عن صحابي واحد."],"ex":[["«متفق عليه»","أعلى درجات الصحيح."]],"q":[["كم شروط الحديث الصحيح؟",["ثلاثة","خمسة","سبعة"],1,""]],"r":[["muqaddima-ibnsalah:2","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","النوع الأول من أنواع علوم الحديث"],["nukhba:6","نخبة الفكر في مصطلح أهل الأثر","الفرد النسبي — …لل ولا شاذ: هو الصحيح لذاته،. [والمراد بالعدل من ل…"],["tadrib:23","تدريب الراوي في شرح تقريب النواوي","حد الصحيح"]],"s":[]},{"id":"hasan","t":"الحسن والضعيف","idea":"الحسن: ما توفرت فيه شروط الصحيح لكن خفّ ضبط بعض رواته. والضعيف: ما فقد شرطاً من شروط القبول.","rules":["الحسن حجة يُعمل به كالصحيح وإن كان دونه.","أسباب الضعف: انقطاع السند (المرسل، المنقطع، المعضل، المعلق)، أو الطعن في الراوي (الكذب، التهمة، فحش الغلط، الجهالة...).","الصحيح لغيره: الحسن إذا تعددت طرقه. والحسن لغيره: الضعيف إذا تعددت طرقه وكان ضعفه يسيراً."],"ex":[["«المرسل»","ما سقط منه الصحابي، فيقول التابعي: قال رسول الله ﷺ."]],"q":[["ما سقط منه الصحابي:",["المعضل","المرسل","المعلق"],1,""]],"r":[["muqaddima-ibnsalah:1","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","معرفة أنواع علوم الحديث، ويعرف بمقدمة ابن الصلاح — … الثاني: معرفه الحسن منه. الثالث: معرفه الضعيف منه…"],["muqaddima-ibnsalah:1","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","معرفة أنواع علوم الحديث، ويعرف بمقدمة ابن الصلاح — … الثالث: معرفه الضعيف منه. الرابع: معرفه المسند. ا…"],["nukhba:11","نخبة الفكر في مصطلح أهل الأثر","ص: 723 — … . والثاني: هو المرسل. والثالث: ان كان باثنين فصاع…"]],"s":[]},{"id":"mawdu","t":"الحديث الموضوع","idea":"الموضوع: الكذب المختلق المنسوب إلى النبي ﷺ، وهو شر الضعيف، وتحرم روايته إلا مع بيان حاله.","rules":["من علاماته: ركاكة اللفظ والمعنى، ومخالفة صريح القرآن والسنة الصحيحة، والمبالغة في الثواب على عمل يسير.","احذر نشر الرسائل المنسوبة للنبي ﷺ قبل التثبت من صحتها."],"ex":[["«من كذب عليّ متعمداً فليتبوأ مقعده من النار»","حديث متواتر في التحذير من الكذب على النبي ﷺ."]],"q":[["رواية الحديث الموضوع دون بيان حاله:",["جائزة في الفضائل","محرمة"],1,""]],"r":[["muqaddima-ibnsalah:22","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","النوع الحادي والعشرون: معرفة الموضوع"],["nukhba:12","نخبة الفكر في مصطلح أهل الأثر","الطعن — …بته] . فالاول: الموضوع والثاني: المتروك. والثالث: …"]],"s":[]},{"id":"jarh","t":"الجرح والتعديل","idea":"علم يُعرف به حال الرواة قبولاً ورداً، وبه حُفظت السنة. وأشهر كتبه: «تهذيب الكمال» و«تقريب التهذيب» لابن حجر، وهو في مكتبة التطبيق.","rules":["ألفاظ التعديل من أعلاها: «ثقة ثبت»، «ثقة حافظ»، ثم «ثقة»، ثم «صدوق».","ألفاظ الجرح: «ضعيف»، «متروك»، «كذاب».","الجرح المفسّر مقدّم على التعديل عند التعارض."],"ex":[["«ثقة ثبت»","من أعلى مراتب التعديل."]],"q":[["أعلى مرتبة:",["صدوق","ثقة ثبت","لا بأس به"],1,""]],"r":[["nukhba:24","نخبة الفكر في مصطلح أهل الأثر","خاتمة — …وجهاله. ومراتب الجرح: واسوؤها الوصف بافعل، كاكذب ا…"],["muqaddima-ibnsalah:25","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","النوع الثالث والعشرون (1)"]],"s":[]},{"id":"kutub","t":"أنواع كتب الحديث","idea":"صنّف العلماء كتب الحديث بطرق مختلفة، ومعرفتها تسهّل البحث والتخريج.","rules":["الصحاح: التي التزم أصحابها الصحة: البخاري ومسلم.","السنن: المرتبة على أبواب الفقه: سنن أبي داود والترمذي والنسائي وابن ماجه.","المسانيد: المرتبة على أسماء الصحابة: مسند أحمد.","الموطآت والمصنفات والمستدركات والأجزاء والأربعينيات."],"ex":[["الكتب الستة","البخاري، ومسلم، وأبو داود، والترمذي، والنسائي، وابن ماجه، وكلها في مكتبة التطبيق."]],"q":[["مسند أحمد مرتب على:",["أبواب الفقه","أسماء الصحابة"],1,""]],"r":[["tadrib:23","تدريب الراوي في شرح تقريب النواوي","حد الصحيح"],["muqaddima-ibnsalah:1","مقدمة ابن الصلاح (معرفة أنواع علوم الحديث)","معرفة أنواع علوم الحديث، ويعرف بمقدمة ابن الصلاح"]],"s":[]}]},"ulumquran":{"ic":"📖","t":"علوم القرآن","d":"نزول القرآن وجمعه وأسباب نزوله والمكي والمدني والناسخ والمنسوخ وإعجازه. من «الإتقان» للسيوطي و«البرهان» للزركشي و«أسباب النزول» للواحدي.","lessons":[{"id":"nuzul","t":"الوحي ونزول القرآن","idea":"نزل القرآن جملة واحدة إلى السماء الدنيا في ليلة القدر، ثم نزل منجّماً (مفرّقاً) على النبي ﷺ في نحو ثلاث وعشرين سنة بحسب الوقائع.","rules":["أول ما نزل: صدر سورة العلق ﴿اقرأ باسم ربك الذي خلق﴾ في غار حراء.","من حكمة نزوله مفرّقاً: تثبيت قلب النبي ﷺ، والتدرّج في التشريع، وتيسير حفظه.","اختُلف في آخر ما نزل، ومن أشهر الأقوال: ﴿واتقوا يوماً ترجعون فيه إلى الله﴾."],"ex":[["﴿وقال الذين كفروا لولا نُزّل عليه القرآن جملة واحدة كذلك لنثبت به فؤادك﴾","حكمة التنجيم."]],"q":[["أول ما نزل من القرآن:",["الفاتحة","صدر سورة العلق","المدثر"],1,"على القول الصحيح."]],"r":[["asbab-nuzul:2","أسباب النزول","القول في أول ما نزل من القرآن"],["itqan:4","الإتقان في علوم القرآن","النوع الأول: في معرفة المكي والمدني (1)"]],"s":[]},{"id":"makki","t":"المكي والمدني","idea":"المكي على الأشهر: ما نزل قبل الهجرة ولو في غير مكة، والمدني: ما نزل بعدها ولو في مكة.","rules":["من سمات المكي: ترسيخ التوحيد واليوم الآخر، وقصص الأنبياء، وقِصر الآيات غالباً، ونداء ﴿يا أيها الناس﴾.","من سمات المدني: الأحكام والتشريع، والجهاد، وذكر المنافقين وأهل الكتاب، ونداء ﴿يا أيها الذين آمنوا﴾.","فائدته: معرفة الناسخ والمنسوخ، وتاريخ التشريع."],"ex":[["سورة البقرة","مدنية: فيها أحكام الصيام والحج والبيوع."]],"q":[["ما نزل بمكة بعد الهجرة (في حجة الوداع مثلاً):",["مكي","مدني"],1,"العبرة بالزمن على الأشهر."]],"r":[["itqan:4","الإتقان في علوم القرآن","النوع الأول: في معرفة المكي والمدني (1)"],["burhan:50","البرهان في علوم القرآن","النوع التاسع: معرفة المكي والمدني (1)"]],"s":[]},{"id":"asbab","t":"أسباب النزول","idea":"سبب النزول: حادثة أو سؤال نزلت الآية بسببه. ومعرفته تعين على فهم الآية فهماً صحيحاً.","rules":["القاعدة: العبرة بعموم اللفظ لا بخصوص السبب.","لا يُعرف سبب النزول إلا بالرواية الصحيحة عمّن شهد التنزيل.","مثال: آيات اللعان نزلت في هلال بن أمية، وحكمها عام."],"ex":[["﴿يسألونك عن الأهلّة﴾","نزلت جواباً لسؤال الصحابة."]],"q":[["القاعدة في أسباب النزول:",["العبرة بخصوص السبب","العبرة بعموم اللفظ"],1,""]],"r":[["asbab-nuzul:1","أسباب النزول","مقدمة المؤلف"],["itqan:1","الإتقان في علوم القرآن","مقدمة — …الفراشي النومي اسباب النزول اول ما نزل اخر ما نزل.…"]],"s":[]},{"id":"jam","t":"جمع القرآن","idea":"جُمع القرآن ثلاث مرات: في صدور الصحابة وفي الرقاع زمن النبي ﷺ، ثم في مصحف واحد زمن أبي بكر بعد استشهاد القرّاء في اليمامة، ثم نسخ عثمان المصاحف وأرسلها إلى الأمصار.","rules":["جمع أبي بكر: تولاه زيد بن ثابت بإشارة عمر رضي الله عنهم.","جمع عثمان: جمع الناس على مصحف واحد بحرف قريش حين اختلفوا في القراءة، وأرسل نسخاً إلى الأمصار.","وكل ذلك تحقيق لقوله: ﴿إنا نحن نزلنا الذكر وإنا له لحافظون﴾."],"ex":[["﴿إنا نحن نزلنا الذكر وإنا له لحافظون﴾","وعد الله بحفظ القرآن."]],"q":[["الصحابي الذي تولى جمع القرآن زمن أبي بكر:",["ابن مسعود","زيد بن ثابت","أبي بن كعب"],1,""]],"r":[["itqan:27","الإتقان في علوم القرآن","النوع الثامن عشر: في جمعه وترتيبه (1)"],["burhan:9","البرهان في علوم القرآن","6- تشنيف المسامع بجمع الجوامع طبع في مجموع شروح جمع الجوامع بمصر سنة 1"]],"s":[]},{"id":"muhkam","t":"المحكم والمتشابه","idea":"المحكم: الواضح المعنى الذي لا يحتمل إلا وجهاً واحداً. والمتشابه: ما يحتمل أوجهاً، ويُرد إلى المحكم ليتضح.","rules":["منهج الراسخين في العلم: ردّ المتشابه إلى المحكم، والإيمان بالجميع.","منهج أهل الزيغ: اتباع المتشابه لإثارة الفتنة."],"ex":[["﴿منه آيات محكمات هن أم الكتاب وأخر متشابهات﴾","آل عمران: ٧."]],"q":[["منهج الراسخين في العلم:",["اتباع المتشابه وحده","رد المتشابه إلى المحكم"],1,""]],"r":[["itqan:80","الإتقان في علوم القرآن","النوع الثالث والأربعون: في المحكم والمتشابه (1)"]],"s":[]},{"id":"ijaz","t":"إعجاز القرآن","idea":"تحدى الله العرب أن يأتوا بمثل القرآن، ثم بعشر سور، ثم بسورة، فعجزوا وهم أهل الفصاحة. وإعجازه في بلاغته ونظمه، وفي إخباره بالغيب، وفي تشريعه.","rules":["مراتب التحدي: بمثله (الإسراء ٨٨)، ثم بعشر سور (هود ١٣)، ثم بسورة (البقرة ٢٣).","وانظر «دلائل الإعجاز» للجرجاني في قسم علوم العربية."],"ex":[["﴿قل لئن اجتمعت الإنس والجن على أن يأتوا بمثل هذا القرآن لا يأتون بمثله﴾","التحدي المطلق."]],"q":[["أقل ما تحدّاهم الله به:",["عشر سور","سورة واحدة"],1,""]],"r":[["itqan:119","الإتقان في علوم القرآن","النوع الرابع والستون: في إعجاز القرآن (1)"],["burhan:94","البرهان في علوم القرآن","النوع الثامن والثلاثون: معرفة إعجازه (1)"]],"s":[]}]},"aqida":{"ic":"🤍","t":"العقيدة على منهج أهل السنة","d":"أصول الاعتقاد من المتون المعتمدة: «العقيدة الطحاوية» وشرحها، و«الواسطية» لابن تيمية، و«لمعة الاعتقاد» لابن قدامة.","lessons":[{"id":"sifat","t":"الأسماء والصفات","idea":"منهج أهل السنة: إثبات ما أثبته الله لنفسه وما أثبته له رسوله ﷺ من الأسماء والصفات، من غير تحريف ولا تعطيل، ومن غير تكييف ولا تمثيل.","rules":["القاعدة الجامعة: ﴿ليس كمثله شيء وهو السميع البصير﴾: نفي المماثلة وإثبات الصفة معاً.","التحريف: تغيير المعنى، والتعطيل: نفي الصفة، والتكييف: السؤال عن الكيفية، والتمثيل: تشبيهها بصفات المخلوقين.","قال الإمام مالك: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عنه بدعة."],"ex":[["﴿ليس كمثله شيء وهو السميع البصير﴾","الشورى: ١١."]],"q":[["منهج أهل السنة في الصفات:",["التأويل","الإثبات بلا تمثيل ولا تعطيل","التفويض المطلق للمعنى"],1,""]],"r":[["wasitiyya:4","العقيدة الواسطية","1- الإيمان بالله"],["lumat:1","لمعة الاعتقاد","وجوب الإيمان بكل ما جاء في القرآن أو صح عن المصطفى من صفات الرحمن وتلق"],["sharh-tahawiyya:14","شرح العقيدة الطحاوية","توحيد الصفات"]],"s":[]},{"id":"iman","t":"حقيقة الإيمان","idea":"الإيمان عند أهل السنة: قول باللسان، واعتقاد بالقلب، وعمل بالجوارح، يزيد بالطاعة وينقص بالمعصية.","rules":["دليل زيادته: ﴿ليزدادوا إيماناً مع إيمانهم﴾.","الإيمان بضع وسبعون شعبة: أعلاها لا إله إلا الله، وأدناها إماطة الأذى عن الطريق.","مرتكب الكبيرة عند أهل السنة مؤمن ناقص الإيمان، لا يخرج من الإسلام، وأمره إلى الله في الآخرة."],"ex":[["﴿إنما المؤمنون الذين إذا ذُكر الله وجلت قلوبهم وإذا تليت عليهم آياته زادتهم إيماناً﴾","الإيمان يزيد."]],"q":[["هل يزيد الإيمان وينقص؟",["نعم","لا"],0,""],["مرتكب الكبيرة عند أهل السنة:",["كافر","مؤمن ناقص الإيمان"],1,""]],"r":[["wasitiyya:3","العقيدة الواسطية","أصول الإيمان وأركانه الست"],["sharh-tahawiyya:3","شرح العقيدة الطحاوية","وجوب الإيمان المجمل على كل أحد"]],"s":[]},{"id":"qadar","t":"مراتب القدر الأربع","idea":"الإيمان بالقدر يقوم على أربع مراتب: العلم، والكتابة، والمشيئة، والخلق.","rules":["العلم: علم الله كل شيء أزلاً.","الكتابة: كتب الله مقادير الخلائق في اللوح المحفوظ قبل خلق السماوات والأرض بخمسين ألف سنة.","المشيئة: ما شاء الله كان وما لم يشأ لم يكن.","الخلق: الله خالق كل شيء، ومنها أفعال العباد، وللعبد مشيئة واختيار يحاسب عليهما."],"ex":[["﴿إنا كل شيء خلقناه بقدر﴾","القمر: ٤٩."]],"q":[["كم مراتب القدر؟",["ثلاث","أربع","خمس"],1,""]],"r":[["wasitiyya:100","العقيدة الواسطية","صفات العفو والمغفرة والرحمة والعزة والقدرة"],["sharh-tahawiyya:44","شرح العقيدة الطحاوية","الرد على قول القدرية والمعتزلة"]],"s":[]},{"id":"sahaba","t":"الصحابة رضي الله عنهم","idea":"يحب أهل السنة أصحاب رسول الله ﷺ جميعاً، ولا يغلون في أحد منهم، ولا يتبرؤون من أحد، ويمسكون عما شجر بينهم.","rules":["أفضلهم: أبو بكر ثم عمر ثم عثمان ثم علي رضي الله عنهم.","العشرة المبشرون بالجنة، وأهل بدر، وأهل بيعة الرضوان.","ويتولّون أهل بيت النبي ﷺ ويحفظون فيهم وصيته."],"ex":[["﴿والسابقون الأولون من المهاجرين والأنصار والذين اتبعوهم بإحسان رضي الله عنهم ورضوا عنه﴾","التوبة: ١٠٠."]],"q":[["أفضل الصحابة:",["عمر","أبو بكر","علي"],1,""]],"r":[["wasitiyya:206","العقيدة الواسطية","الأصل الخامس: في الصحابة رضي الله عنهم"],["sharh-tahawiyya:225","شرح العقيدة الطحاوية","نقول الصحابة في زيادة الإيمان ونقصانه"],["lumat:14","لمعة الاعتقاد","محمد خاتم النبيين — …لصلاه علي جميع الصحابه رضي الله عنهم، واجماع الصحا…"]],"s":[]},{"id":"akhira","t":"الإيمان باليوم الآخر وأحواله","idea":"يؤمن أهل السنة بكل ما أخبر به النبي ﷺ مما يكون بعد الموت: فتنة القبر ونعيمه وعذابه، ثم البعث والحشر والحساب والميزان والصراط والحوض والشفاعة، والجنة والنار.","rules":["الجنة والنار مخلوقتان الآن، لا تفنيان.","رؤية المؤمنين ربهم في الجنة حق: ﴿وجوه يومئذ ناضرة إلى ربها ناظرة﴾.","الشفاعة حق، وأعظمها الشفاعة العظمى لنبينا ﷺ."],"ex":[["﴿وجوه يومئذ ناضرة إلى ربها ناظرة﴾","القيامة: ٢٢–٢٣."]],"q":[["رؤية المؤمنين ربهم في الجنة:",["ثابتة","غير ثابتة"],0,""]],"r":[["wasitiyya:234","العقيدة الواسطية","الفصل الأول: الإيمان بكل ما أخبر به النبي صلى الله عليه وسلم مما يكون بعد الموت — …• ومن الايمان باليوم الاخر:…"],["sharh-tahawiyya:114","شرح العقيدة الطحاوية","الرد على المعتزلة في نفي الرؤية"]],"s":[]}]},"madhahib":{"ic":"🕌","t":"المذاهب الفقهية الأربعة","d":"الأئمة الأربعة ومتونهم المعتمدة، وكيف تدرس الفقه على مذهب ثم تنتقل إلى الفقه المقارن بالدليل.","lessons":[{"id":"aimma","t":"الأئمة الأربعة","idea":"المذاهب الفقهية المتبوعة عند أهل السنة أربعة، وكلهم أئمة هدى، واختلافهم في الفروع رحمة وسعة، وكلهم أوصى باتباع الدليل.","rules":["أبو حنيفة النعمان (ت ١٥٠هـ) بالكوفة: من متونه «مختصر القدوري».","مالك بن أنس (ت ١٧٩هـ) إمام دار الهجرة: من متونه «الرسالة» لابن أبي زيد القيرواني.","محمد بن إدريس الشافعي (ت ٢٠٤هـ): من متونه «متن أبي شجاع».","أحمد بن حنبل (ت ٢٤١هـ): من متونه «زاد المستقنع» وشرحه «الروض المربع»، و«عمدة الفقه».","وللفقه المقارن بالدليل: «بداية المجتهد» لابن رشد، و«المغني» لابن قدامة، وهما في المكتبة."],"ex":[["قول الشافعي: «إذا صح الحديث فهو مذهبي»","من أقوال الأئمة في تقديم الدليل."]],"q":[["صاحب «الموطأ»:",["أبو حنيفة","مالك","أحمد"],1,""]],"r":[["quduri:2","مختصر القدوري — الحنفي","1 - كتاب الطهارة"],["risala-qayrawani:1","الرسالة — المالكي","مقدمة"],["abushuja:2","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الطهارة"],["zad-mustaqni:2","زاد المستقنع — الحنبلي","باب الآنية"]],"s":[]},{"id":"manhaj","t":"كيف تدرس الفقه؟","idea":"الطريقة التي سار عليها العلماء: أن تبدأ بمتن مختصر في مذهب واحد على يد شيخ، ثم شرحه، ثم الفقه المقارن بالأدلة، ثم كتب الخلاف الموسعة.","rules":["المرحلة الأولى: متن مختصر (أبو شجاع، أو القدوري، أو الرسالة، أو عمدة الفقه / زاد المستقنع).","المرحلة الثانية: شرح المتن مع أدلته (مثل الروض المربع)، وكتاب أحاديث الأحكام (عمدة الأحكام، ثم بلوغ المرام).","المرحلة الثالثة: الفقه المقارن: بداية المجتهد، ثم المغني.","احترم الخلاف المعتبر، وانقل الأقوال بأدلتها."],"ex":[["«عمدة الأحكام» ثم «بلوغ المرام»","كتابان في أحاديث الأحكام مرتبان على أبواب الفقه، وكلاهما في المكتبة."]],"q":[["أي ترتيب أصح للمبتدئ؟",["المغني ثم المتن","المتن ثم الشرح ثم المقارن"],1,""]],"r":[["umdat-ahkam:3","عمدة الأحكام من كلام خير الأنام","مقدمة المؤلف"],["rawd-murbi:1","الروض المربع شرح زاد المستقنع","مقدمة"]],"s":[]}]},"tazkiya":{"ic":"🌱","t":"التزكية وأعمال القلوب","d":"صلاح القلب أساس صلاح العمل: الإخلاص، والتوبة، والصبر، والشكر، والتوكل، وعلاج أمراض القلوب. من «مدارج السالكين» و«الوابل الصيب» و«مختصر منهاج القاصدين».","lessons":[{"id":"ikhlas","t":"الإخلاص","idea":"الإخلاص: أن تقصد بعملك وجه الله وحده، لا مدح الناس ولا الدنيا. وهو شرط قبول كل عمل مع موافقة السنة.","rules":["«إنما الأعمال بالنيات» أصل في الإخلاص.","الرياء: أن تعمل ليراك الناس، وهو الشرك الأصغر.","من علاج الرياء: إخفاء العمل الصالح ما أمكن، وتذكّر أن الناس لا يملكون لك نفعاً ولا ضراً."],"ex":[["﴿وما أُمروا إلا ليعبدوا الله مخلصين له الدين﴾","البينة: ٥."]],"q":[["شرطا قبول العمل:",["الإخلاص والمتابعة","الكثرة والشهرة"],0,""]],"r":[["madarij:42","مدارج السالكين","أهل الإخلاص للمعبود والمتابعة"],["mukhtasar-minhaj:204","مختصر منهاج القاصدين","8 باب في النية والإخلاص والصدق"]],"s":[]},{"id":"tawba","t":"التوبة","idea":"التوبة أول منازل السالكين وأوسطها وآخرها، فلا يستغني عنها أحد. وشروطها: الإقلاع عن الذنب، والندم عليه، والعزم على عدم العودة، ورد المظالم إلى أهلها.","rules":["التوبة تمحو ما قبلها، والله يفرح بتوبة عبده.","لا تيأس مهما تكرر الذنب، وجدّد التوبة كلما وقعت."],"ex":[["﴿وتوبوا إلى الله جميعاً أيُّهَ المؤمنون لعلكم تفلحون﴾","النور: ٣١."]],"q":[["من شروط التوبة من حقوق الناس:",["رد المظالم","الصدقة فقط"],0,""]],"r":[["madarij:72","مدارج السالكين","من منزلة المحاسبة يصح له نزول منزلة التوبة"],["mukhtasar-minhaj:145","مختصر منهاج القاصدين","الربع الرابع: ربع المنجيات كتاب التوبة وذكر شروطها وأركانها وما يتعلق "]],"s":[]},{"id":"sabr","t":"الصبر والشكر","idea":"الصبر ثلاثة أنواع: صبر على طاعة الله، وصبر عن معصيته، وصبر على أقداره المؤلمة. والشكر: الاعتراف بالنعمة واستعمالها في طاعة المنعم. والمؤمن بين الصبر والشكر دائماً.","rules":["قال ابن القيم: السعادة في ثلاث: إذا أُعطي شكر، وإذا ابتلي صبر، وإذا أذنب استغفر.","«عجباً لأمر المؤمن، إن أمره كله خير»."],"ex":[["﴿لئن شكرتم لأزيدنكم﴾","إبراهيم: ٧."]],"q":[["الصبر على أداء الصلاة في وقتها نوعه:",["صبر على الطاعة","صبر عن المعصية"],0,""]],"r":[["wabil:1","الوابل الصيب من الكلم الطيب","السعادة بثلاث: شكر النعمة، والصبر على البلاء، والتوبة من الذنب"],["madarij:267","مدارج السالكين","الصبر في الكتاب والسنة"],["mukhtasar-minhaj:154","مختصر منهاج القاصدين","كتاب الصبر (1) والشكر"]],"s":[]},{"id":"tawakkul","t":"التوكل","idea":"التوكل: صدق اعتماد القلب على الله في جلب المنافع ودفع المضار، مع الأخذ بالأسباب. فترك الأسباب عجز، والاعتماد عليها وحدها شرك خفي.","rules":["«اعقلها وتوكل».","من ثمراته: الطمأنينة، وذهاب القلق على الرزق."],"ex":[["﴿ومن يتوكل على الله فهو حسبه﴾","الطلاق: ٣."]],"q":[["التوكل الصحيح:",["ترك الأسباب","الأخذ بالأسباب مع اعتماد القلب على الله"],1,""]],"r":[["madarij:236","مدارج السالكين","التوكل في الكتاب والسنة"],["mukhtasar-minhaj:193","مختصر منهاج القاصدين","بيان فضيلة التوكل"]],"s":[]},{"id":"amrad","t":"أمراض القلوب: الكبر والحسد","idea":"الكبر: بطر الحق (ردّه) وغمط الناس (احتقارهم). والحسد: تمني زوال نعمة الغير. وكلاهما يأكل الحسنات ويُفسد القلب.","rules":["علاج الكبر: معرفة النفس وأصلها، ومخالطة الضعفاء، والتواضع للحق.","علاج الحسد: الرضا بقسمة الله، والدعاء للمحسود بالبركة، و«الغبطة» جائزة: أن تتمنى مثل نعمته دون زوالها عنه."],"ex":[["«لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر»","رواه مسلم."]],"q":[["تمني مثل نعمة غيرك دون زوالها عنه:",["حسد محرم","غبطة جائزة"],1,""]],"r":[["mukhtasar-minhaj:133","مختصر منهاج القاصدين","كتاب ذم الكبر والعجب"],["mukhtasar-minhaj:104","مختصر منهاج القاصدين","كتاب ذم الغضب والحقد والحسد"]],"s":[]},{"id":"dhikr","t":"ذكر الله","idea":"الذكر حياة القلب، وهو أيسر العبادات وأعظمها أجراً. وقد جمع ابن القيم في «الوابل الصيب» أكثر من سبعين فائدة للذكر.","rules":["من فوائده: يطرد الشيطان، ويرضي الرحمن، ويزيل الهم، ويقوّي القلب والبدن.","أفضل الذكر: القرآن، ثم «لا إله إلا الله».","وفي التطبيق قسم الأذكار والأدعية والمسبحة."],"ex":[["﴿ألا بذكر الله تطمئن القلوب﴾","الرعد: ٢٨."]],"q":[["أفضل الذكر:",["القرآن","الشعر"],0,""]],"r":[["wabil:10","الوابل الصيب من الكلم الطيب","ذكر الله وفوائده"],["wabil:87","الوابل الصيب من الكلم الطيب","الفصل الثاني الذكر أفضل من الدعاء"]],"s":[]}]},"muamalat":{"ic":"💼","t":"المعاملات المالية","d":"أحكام البيع والشراء والدَّين والربا والتقسيط والشركات، مأخوذة من أبوابها في كتب الفقه المقارن (بداية المجتهد، والمغني) وكتب أحاديث الأحكام.","lessons":[{"id":"asl","t":"الأصل في المعاملات الإباحة","idea":"القاعدة: الأصل في العقود والمعاملات الحِلّ، إلا ما دل الدليل على تحريمه. وأسباب التحريم ترجع غالباً إلى ثلاثة: الربا، والغرر، والظلم (أكل المال بالباطل).","rules":["بخلاف العبادات: الأصل فيها المنع حتى يرد الدليل.","من شروط البيع: التراضي، وأن يكون البائع مالكاً أو مأذوناً له، وأن تكون السلعة معلومة مقدوراً على تسليمها، والثمن معلوماً."],"ex":[["﴿يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم﴾","النساء: ٢٩."]],"q":[["الأصل في المعاملات:",["التحريم","الإباحة"],1,""]],"r":[["bidayat:279","بداية المجتهد ونهاية المقتصد","الجزء الأول أنواع البيوع المطلقة"],["mughni:2150","المغني","كتاب البيوع"]],"s":[]},{"id":"riba","t":"الربا وأنواعه","idea":"الربا نوعان: ربا الديون (النسيئة): كل زيادة مشروطة على القرض أو الدَّين مقابل الأجل، وهو ربا الجاهلية. وربا البيوع: في الأصناف الربوية (الذهب والفضة وما في معناهما من النقود، والأطعمة المذكورة في الحديث).","rules":["بيع الذهب بالذهب، والعملة بالعملة نفسها: يُشترط التماثل والتقابض في المجلس.","بيع ذهب بعملة، أو عملة بعملة أخرى: يُشترط التقابض في المجلس فقط.","كل قرض جرّ منفعة مشروطة فهو ربا.","غرامة التأخير على المدين المشروطة في العقد من ربا الديون عند جمهور العلماء المعاصرين."],"ex":[["«الذهب بالذهب، والفضة بالفضة... مثلاً بمثل، يداً بيد»","رواه مسلم من حديث عبادة بن الصامت."]],"q":[["صرف ريالات بدولارات:",["يجوز مؤجلاً","يُشترط التقابض في المجلس"],1,""]],"r":[["bidayat:281","بداية المجتهد ونهاية المقتصد","الباب الثاني في بيوع الربا"],["mughni:1072","المغني","فصل أدرك ركعة من المغرب أو الرباعية في صلاة الخوف"]],"s":[]},{"id":"taqsit","t":"البيع بالتقسيط والأجل","idea":"البيع بثمن مؤجل أو مقسّط أعلى من ثمن النقد جائز عند جمهور العلماء، لأنه بيع لا قرض، والزيادة في مقابل الأجل في البيع ليست ربا.","rules":["الشروط: أن يكون البائع مالكاً للسلعة قبل بيعها، وأن يُحدَّد الثمن والأقساط عند العقد (لا يُترك مفتوحاً)، وألا تُشترط زيادة على المدين إن تأخر في السداد.","إن تأخر المشتري المعسر وجب إنظاره: ﴿وإن كان ذو عسرة فنظرة إلى ميسرة﴾، والمماطل الغني ظالم.","المرابحة للآمر بالشراء: أجازها كثير من المعاصرين بشرط أن يتملك البائع (البنك مثلاً) السلعة ويقبضها قبل بيعها."],"ex":[["﴿وأحلّ الله البيع وحرّم الربا﴾","البقرة: ٢٧٥."]],"q":[["البيع بالتقسيط بثمن أعلى من النقد:",["ربا محرم","جائز عند الجمهور بشروطه"],1,""],["اشتراط غرامة على تأخر الأقساط:",["جائز","لا يجوز لأنه ربا"],1,""]],"r":[["bidayat:279","بداية المجتهد ونهاية المقتصد","الجزء الأول أنواع البيوع المطلقة"],["mughni:967","المغني","فصل تحريم البيع ووجوب السعي يختص بالمخاطبين بالجمعة"]],"s":[]},{"id":"gharar","t":"الغرر والميسر","idea":"الغرر: الجهالة والخطر في العقد بحيث لا يدري أحد الطرفين ما يحصل عليه. والميسر (القمار): كل معاملة يدور فيها الطرف بين الغُنم والغُرم بلا مقابل حقيقي.","rules":["نهى النبي ﷺ عن بيع الغرر، كبيع السمك في الماء والطير في الهواء.","الغرر اليسير التابع معفو عنه، كأساسات البيت.","من صور الميسر: المراهنات واليانصيب."],"ex":[["«نهى رسول الله ﷺ عن بيع الحصاة وعن بيع الغرر»","رواه مسلم."]],"q":[["شراء تذكرة يانصيب:",["جائز","ميسر محرم"],1,""]],"r":[["bidayat:133","بداية المجتهد ونهاية المقتصد","الصيام المندوب إليه — … وست من شوال، والغرر من كل شهر (وهي: الثالث عشر، و…"],["mughni:2165","المغني","فصل بيوع الأعيان المرئية — …نه «نهي عن بيع الغرر» . رواه مسلم ولانه باع ما لم …"]],"s":[]},{"id":"sharika","t":"الشركة والمضاربة","idea":"الشركة: اشتراك اثنين فأكثر في مال أو عمل للربح. والمضاربة: مال من طرف وعمل من طرف، والربح بينهما بنسبة متفق عليها.","rules":["يُحدد الربح نسبة شائعة (مثل ٣٠٪ من الربح) لا مبلغاً مقطوعاً.","في المضاربة الخسارة على صاحب المال، ويخسر العامل جهده، إلا إذا فرّط أو تعدّى.","ضمان رأس المال للمستثمر يحوّل العقد إلى قرض بفائدة."],"ex":[["شراكة: أنا بالمال وأنت بالعمل والربح مناصفة","مضاربة صحيحة."]],"q":[["اشتراط ربح ثابت شهري للمستثمر:",["جائز","لا يجوز"],1,"يُحدد الربح نسبة شائعة."]],"r":[["bidayat:342","بداية المجتهد ونهاية المقتصد","الركن الأول محل شركة العنان من الأموال — والنظر في الشركة: في أنواعها،"],["bidayat:338","بداية المجتهد ونهاية المقتصد","الباب الأول في محل القراض"],["mughni:2920","المغني","فصل في شركة المضاربة"]],"s":[]},{"id":"dayn","t":"آداب الدَّين والقرض","idea":"القرض الحسن من القربات، والدَّين أمانة ثقيلة. أمر الله بكتابته، وحذّر النبي ﷺ من المماطلة.","rules":["اكتب الدَّين ووثّقه: ﴿يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه﴾.","«مطل الغني ظلم».","من نوى السداد أعانه الله، ومن أخذها يريد إتلافها أتلفه الله."],"ex":[["آية الدَّين","أطول آية في القرآن: البقرة ٢٨٢."]],"q":[["تأخير الغني سداد الدين:",["جائز","ظلم"],1,""]],"r":[["bidayat:286","بداية المجتهد ونهاية المقتصد","فصل بيع الربوي الرطب بجنسه من اليابس — …ع، وقصده، ولفظ القرض وقصده. ولما كانت اصول الربا ك…"],["mughni:2185","المغني","فصل شرط الخيار حيلة على الانتفاع بالقرض"]],"s":[]}]},"tibb":{"ic":"🌿","t":"الطب النبوي","d":"هدي النبي ﷺ في الصحة والتداوي، من كتاب «الطب النبوي» لابن القيم، مع التنبيه: ما ورد من العلاجات لا يغني عن مراجعة الطبيب.","lessons":[{"id":"tadawi","t":"التداوي مشروع","idea":"أمر النبي ﷺ بالتداوي، وأخبر أن الله ما أنزل داء إلا أنزل له دواء، علمه من علمه وجهله من جهله. والتداوي لا ينافي التوكل.","rules":["«تداووا عباد الله، فإن الله لم يضع داء إلا وضع له دواء» رواه أبو داود والترمذي.","لا يُتداوى بالمحرم.","مراجعة الطبيب المختص من الأخذ بالأسباب."],"ex":[["«ما أنزل الله داء إلا أنزل له شفاء»","رواه البخاري."]],"q":[["التداوي:",["ينافي التوكل","لا ينافي التوكل"],1,""]],"r":[["tibb-nabawi:2","الطب النبوي","فصول نافعة في هديه صلى الله عليه وسلم في الطب الذي تطبب به ووصفه لغيره"],["zad:234","زاد المعاد في هدي خير العباد","وهم محب الدين الطبري بقوله خرج صلى الله عليه وسلم يوم الجمعة بعد الصلا"]],"s":[]},{"id":"hulul","t":"العسل والحبة السوداء والحجامة","idea":"وردت أحاديث صحيحة في منافع العسل والحبة السوداء والحجامة، وشرح ابن القيم وجوه الانتفاع بها.","rules":["العسل: ﴿فيه شفاء للناس﴾ (النحل: ٦٩).","الحبة السوداء: «إن في الحبة السوداء شفاء من كل داء إلا السام» (الموت) متفق عليه.","الحجامة: «إن أمثل ما تداويتم به الحجامة» متفق عليه.","تنبيه: لكل علاج مقدار وموضع، فلا تترك علاج الطبيب، واستشره قبل الاستعمال إن كانت لديك حالة مرضية."],"ex":[["﴿يخرج من بطونها شراب مختلف ألوانه فيه شفاء للناس﴾","النحل: ٦٩."]],"q":[["«السام» في الحديث معناه:",["السم","الموت"],1,""]],"r":[["tibb-nabawi:14","الطب النبوي","فصل في هديه في العلاج بشرب العسل، والحجامة، والكي"],["tibb-nabawi:115","الطب النبوي","حرف الحاء — …ل: «عليكم بهذه الحبه السوداء، فان فيها شفاء من كل …"],["tibb-nabawi:14","الطب النبوي","فصل في هديه في العلاج بشرب العسل، والحجامة، والكي"]],"s":[]},{"id":"wiqaya","t":"الوقاية وآداب الطعام","idea":"من هديه ﷺ في حفظ الصحة: الاعتدال في الطعام والشراب، والنظافة، والحجر الصحي عند الوباء.","rules":["«ما ملأ آدمي وعاء شراً من بطن، بحسب ابن آدم لقيمات يقمن صلبه» رواه الترمذي.","في الطاعون: «إذا سمعتم به بأرض فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها فلا تخرجوا فراراً منه» متفق عليه.","غسل اليدين، وتغطية الإناء، والسواك."],"ex":[["﴿وكلوا واشربوا ولا تسرفوا﴾","الأعراف: ٣١: أصل في حفظ الصحة."]],"q":[["الحجر الصحي له أصل في:",["حديث الطاعون","لا أصل له"],0,""]],"r":[["tibb-nabawi:108","الطب النبوي","فصل في هديه صلى الله عليه وسلم في حفظ الصحة بالطيب"],["tibb-nabawi:10","الطب النبوي","فصل — …في هديه في الطاعون، وعلاجه، والاحتراز منه في «…"]],"s":[]}]},"tafsir":{"ic":"🕋","t":"تفسير قصار السور","d":"معاني السور التي نقرؤها كل يوم في الصلاة، مختصرة من «تفسير السعدي» و«تفسير ابن كثير»، مع فوائد وتدبر.","lessons":[{"id":"fatiha","t":"سورة الفاتحة","idea":"أم القرآن وأعظم سورة فيه، تُقرأ في كل ركعة. أولها ثناء على الله، ووسطها عهد بين العبد وربه: ﴿إياك نعبد وإياك نستعين﴾، وآخرها أعظم دعاء: الهداية إلى الصراط المستقيم.","rules":["﴿الحمد لله رب العالمين﴾: الثناء الكامل لله المربي لجميع الخلق بنعمه.","﴿مالك يوم الدين﴾: يوم الجزاء والحساب.","﴿إياك نعبد﴾: لا نعبد إلا أنت، ﴿وإياك نستعين﴾: لا نستعين إلا بك؛ وتقديم المفعول يفيد الحصر.","﴿المغضوب عليهم﴾: من عرف الحق وتركه، ﴿الضالين﴾: من عمل بغير علم."],"ex":[["﴿اهدنا الصراط المستقيم﴾","نسأل الله الدلالة على الحق والتوفيق للعمل به والثبات عليه."]],"q":[["معنى ﴿إياك نعبد﴾:",["نعبدك ونعبد غيرك","لا نعبد إلا أنت"],1,"تقديم «إياك» يفيد الحصر."],["«المغضوب عليهم» هم:",["من عرف الحق وترك العمل به","من جهل الحق"],0,""]],"r":[["tafsir-saadi:1:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الفاتحة"],["tafsir-ibnkathir:1:1","تفسير القرآن العظيم","تفسير سورة الفاتحة"]],"s":[]},{"id":"asr","t":"سورة العصر","idea":"أقسم الله بالعصر (الدهر والزمن) أن كل إنسان في خسارة، إلا من جمع أربع صفات: الإيمان، والعمل الصالح، والتواصي بالحق، والتواصي بالصبر.","rules":["نُقل عن الشافعي رحمه الله أن الناس لو تدبروا هذه السورة لوسعتهم (ذكره ابن كثير).","بالإيمان والعمل يكمّل الإنسان نفسه، وبالتواصي يكمّل غيره."],"ex":[["﴿وتواصوا بالحق وتواصوا بالصبر﴾","الدعوة إلى الخير والصبر على طاعة الله وعن معصيته وعلى أقداره."]],"q":[["كم صفة يخرج بها الإنسان من الخسارة؟",["اثنتان","أربع","ست"],1,""]],"r":[["tafsir-saadi:103:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة العصر"],["tafsir-ibnkathir:103:1","تفسير القرآن العظيم","تفسير سورة العصر"]],"s":[]},{"id":"kawthar","t":"سورة الكوثر","idea":"بشّر الله نبيه ﷺ بالخير الكثير، ومنه نهر الكوثر في الجنة وحوضه يوم القيامة، وأمره بشكر النعمة بالصلاة والنحر خالصين لله، وأخبر أن مبغضه هو المقطوع من كل خير.","rules":["الكوثر: الخير الكثير، ومنه نهر في الجنة، كما في صحيح مسلم.","﴿فصلّ لربك وانحر﴾: اجعل صلاتك وذبحك لله وحده، خلافاً للمشركين.","﴿إن شانئك هو الأبتر﴾: الأبتر: المقطوع ذكره وخيره."],"ex":[["﴿إنا أعطيناك الكوثر﴾","أقصر سورة في القرآن."]],"q":[["«شانئك» معناها:",["مبغضك","صاحبك"],0,""]],"r":[["tafsir-saadi:108:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الكوثر"],["tafsir-ibnkathir:108:1","تفسير القرآن العظيم","تفسير سورة الكوثر"]],"s":[]},{"id":"ikhlas","t":"سورة الإخلاص","idea":"سورة التوحيد الخالص: فيها صفة الرب سبحانه، وتعدل ثلث القرآن كما في الصحيح.","rules":["﴿الله أحد﴾: المتفرد بالكمال، لا شريك له.","﴿الله الصمد﴾: السيد الكامل الذي تقصده الخلائق في حوائجها.","﴿لم يلد ولم يولد﴾: نفي الولد والوالد، ردّاً على النصارى والمشركين.","﴿ولم يكن له كفواً أحد﴾: لا مثيل له ولا شبيه."],"ex":[["«قل هو الله أحد تعدل ثلث القرآن»","رواه البخاري."]],"q":[["معنى «الصمد»:",["الذي تقصده الخلائق في حوائجها","القوي فقط"],0,""],["سورة الإخلاص تعدل:",["ربع القرآن","ثلث القرآن"],1,""]],"r":[["tafsir-saadi:112:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الإخلاص"],["tafsir-ibnkathir:112:1","تفسير القرآن العظيم","تفسير سورة الإخلاص"]],"s":[]},{"id":"muawwidhat","t":"المعوّذتان: الفلق والناس","idea":"سورتان للتحصّن بالله: الفلق للاستعاذة من الشرور الخارجية (شر المخلوقات، والليل، والسحر، والحسد)، والناس للاستعاذة من الشر الداخلي: وسوسة الشيطان.","rules":["﴿الفلق﴾: الصبح.","﴿غاسق إذا وقب﴾: الليل إذا أظلم.","﴿النفاثات في العقد﴾: السواحر.","﴿الوسواس الخناس﴾: الشيطان يوسوس، فإذا ذُكر الله خنس وتأخّر.","من السنة قراءتهما مع الإخلاص صباحاً ومساءً ثلاثاً، وعند النوم."],"ex":[["﴿من شر الوسواس الخناس﴾","الخناس: الذي يتأخر ويختفي عند ذكر الله."]],"q":[["«النفاثات في العقد»:",["السواحر","الرياح"],0,""],["معنى «الفلق»:",["الليل","الصبح"],1,""]],"r":[["tafsir-saadi:113:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الفلق"],["tafsir-ibnkathir:113:1","تفسير القرآن العظيم","تفسير سورة الفلق"],["tafsir-saadi:114:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الناس"],["tafsir-ibnkathir:114:1","تفسير القرآن العظيم","تفسير سورة الناس"]],"s":[]},{"id":"maun","t":"سورة الماعون","idea":"تذم من يكذّب بالجزاء فلا يرحم اليتيم ولا يحث على إطعام المسكين، وتذم المصلين الساهين عن صلاتهم المرائين المانعين للخير.","rules":["﴿يدعّ اليتيم﴾: يدفعه بعنف.","﴿عن صلاتهم ساهون﴾: يؤخرونها عن وقتها أو يضيعون أركانها، وليس المراد السهو في أثنائها.","﴿ويمنعون الماعون﴾: يمنعون العارية والمعونة اليسيرة كالإناء والفأس."],"ex":[["﴿فويل للمصلين الذين هم عن صلاتهم ساهون﴾","قال: «عن صلاتهم» لا «في صلاتهم»."]],"q":[["المقصود بالساهين:",["من سها في صلاته فسجد للسهو","من يضيع الصلاة ويؤخرها عن وقتها"],1,""]],"r":[["tafsir-saadi:107:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الماعون"],["tafsir-ibnkathir:107:1","تفسير القرآن العظيم","تفسير سورة الماعون"]],"s":[]},{"id":"fil","t":"سورتا الفيل وقريش","idea":"الفيل: قصة أبرهة الذي جاء بجيشه وفيله لهدم الكعبة عام مولد النبي ﷺ، فأهلكه الله بطير أبابيل. وقريش: تذكير قريش بنعمة الأمن والرزق في رحلتي الشتاء والصيف، ليعبدوا رب هذا البيت.","rules":["﴿طيراً أبابيل﴾: جماعات متتابعة.","﴿بحجارة من سجيل﴾: من طين متحجر.","﴿كعصف مأكول﴾: كورق الزرع الذي أكلته الدواب.","﴿الذي أطعمهم من جوع وآمنهم من خوف﴾: نعمتا الرزق والأمن تستوجبان العبادة."],"ex":[["عام الفيل","وُلد فيه النبي ﷺ على المشهور."]],"q":[["رحلتا قريش:",["الشتاء والصيف","الربيع والخريف"],0,""]],"r":[["tafsir-saadi:105:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الفيل"],["tafsir-ibnkathir:105:1","تفسير القرآن العظيم","تفسير سورة الفيل"],["tafsir-saadi:106:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة قريش"],["tafsir-ibnkathir:106:1","تفسير القرآن العظيم","تفسير سورة قريش"]],"s":[]},{"id":"takathur","t":"سورة التكاثر","idea":"تحذّر من الانشغال بالتفاخر بكثرة الأموال والأولاد حتى يأتي الموت، وتذكّر بالسؤال يوم القيامة عن النعيم.","rules":["﴿حتى زرتم المقابر﴾: حتى متم ودُفنتم.","﴿ثم لتسألن يومئذ عن النعيم﴾: عن كل نعمة: هل شكرتها؟ حتى الماء البارد والظل."],"ex":[["﴿ألهاكم التكاثر﴾","شغلكم التفاخر بالكثرة عن طاعة الله."]],"q":[["«زرتم المقابر» معناها:",["زيارة القبور","الموت والدفن"],1,""]],"r":[["tafsir-saadi:102:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة التكاثر"],["tafsir-ibnkathir:102:1","تفسير القرآن العظيم","تفسير سورة التكاثر"]],"s":[]},{"id":"zalzala","t":"سورة الزلزلة","idea":"تصف أهوال يوم القيامة: زلزلة الأرض، وإخراجها ما في بطنها، وشهادتها بما عُمل عليها، ثم الجزاء الدقيق على مثقال الذرة.","rules":["﴿تحدّث أخبارها﴾: تشهد على العباد بما عملوا عليها.","﴿فمن يعمل مثقال ذرة خيراً يره﴾: لا تحقرن من المعروف شيئاً، ولا من الذنوب شيئاً."],"ex":[["﴿ومن يعمل مثقال ذرة شراً يره﴾","دقة الحساب."]],"q":[["معنى ﴿تحدث أخبارها﴾:",["تشهد بما عُمل عليها","تتزلزل فقط"],0,""]],"r":[["tafsir-saadi:99:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الزلزلة"],["tafsir-ibnkathir:99:1","تفسير القرآن العظيم","تفسير سورة الزلزلة"]],"s":[]},{"id":"qadr","t":"سورة القدر","idea":"تبيّن فضل ليلة القدر: نزل فيها القرآن، وهي خير من ألف شهر، وتتنزّل فيها الملائكة، وهي سلام حتى مطلع الفجر. وهي في العشر الأواخر من رمضان، وأرجاها ليالي الوتر.","rules":["﴿خير من ألف شهر﴾: العمل فيها خير من العمل في ألف شهر ليس فيها ليلة القدر.","﴿والروح﴾: جبريل عليه السلام.","من دعائها: «اللهم إنك عفو تحب العفو فاعف عني» رواه الترمذي."],"ex":[["﴿إنا أنزلناه في ليلة القدر﴾","نزول القرآن من اللوح المحفوظ إلى السماء الدنيا."]],"q":[["ليلة القدر خير من:",["مائة شهر","ألف شهر"],1,""],["«الروح» في السورة:",["جبريل","روح الإنسان"],0,""]],"r":[["tafsir-saadi:97:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة القدر"],["tafsir-ibnkathir:97:1","تفسير القرآن العظيم","تفسير سورة القدر"]],"s":[]},{"id":"duha","t":"سورتا الضحى والشرح","idea":"نزلت الضحى لما فتر الوحي فقال المشركون: ودّعه ربه، فطمأنه الله بأنه لم يتركه، وذكّره بنعمه، وأمره بالإحسان لليتيم والسائل والتحديث بالنعمة. والشرح: تذكير بنعمة شرح الصدر، والبشرى بأن مع العسر يسراً.","rules":["﴿ما ودّعك ربك وما قلى﴾: ما تركك وما أبغضك.","﴿فأما اليتيم فلا تقهر وأما السائل فلا تنهر﴾.","﴿فإن مع العسر يسراً إن مع العسر يسراً﴾: قيل: لن يغلب عسر يسرين، لأن العسر معرّف مكرر فهو واحد، واليسر منكّر فهو اثنان."],"ex":[["﴿وأما بنعمة ربك فحدّث﴾","إظهار النعمة شكراً لا فخراً."]],"q":[["«وما قلى» معناها:",["وما أبغضك","وما نسيك"],0,""]],"r":[["tafsir-saadi:93:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الضحى"],["tafsir-ibnkathir:93:1","تفسير القرآن العظيم","تفسير سورة الضحى"],["tafsir-saadi:94:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الشرح"],["tafsir-ibnkathir:94:1","تفسير القرآن العظيم","تفسير سورة الشرح"]],"s":[]},{"id":"kafirun","t":"سور الكافرون والنصر والمسد","idea":"الكافرون: براءة من الشرك، وفصل بين عبادة المسلم وعبادة المشركين، وتعدل ربع القرآن. والنصر: بشارة بالفتح ودخول الناس في الدين أفواجاً، وإشارة إلى قرب أجله ﷺ. والمسد: وعيد أبي لهب وامرأته لعداوتهما للنبي ﷺ.","rules":["﴿لكم دينكم ولي دين﴾: براءة لا مداهنة فيها، لا إقرار للباطل.","كان النبي ﷺ يقرأ الكافرون والإخلاص في ركعتي الفجر وركعتي الطواف.","﴿فسبح بحمد ربك واستغفره﴾: كان ﷺ يكثر بعدها من قول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي."],"ex":[["﴿تبت يدا أبي لهب وتب﴾","خسرت يداه وخسر."]],"q":[["معنى ﴿لكم دينكم ولي دين﴾:",["إقرار بصحة دينهم","براءة من دينهم"],1,""]],"r":[["tafsir-saadi:109:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة الكافرون"],["tafsir-ibnkathir:109:1","تفسير القرآن العظيم","تفسير سورة الكافرون"],["tafsir-saadi:110:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة النصر"],["tafsir-ibnkathir:110:1","تفسير القرآن العظيم","تفسير سورة النصر"],["tafsir-saadi:111:1","تيسير الكريم الرحمن في تفسير كلام المنان","تفسير سورة المسد"],["tafsir-ibnkathir:111:1","تفسير القرآن العظيم","تفسير سورة المسد"]],"s":[]}]},"sira":{"ic":"🌙","t":"السيرة النبوية: مسار متسلسل","d":"حياة النبي ﷺ من المولد إلى الوفاة في دروس قصيرة متتابعة، من «سيرة ابن هشام» و«زاد المعاد» و«البداية والنهاية».","lessons":[{"id":"mawlid","t":"النسب والمولد والنشأة","idea":"هو محمد بن عبد الله بن عبد المطلب بن هاشم، من قريش، من ولد إسماعيل بن إبراهيم عليهما السلام. وُلد بمكة عام الفيل يوم الاثنين في شهر ربيع الأول على المشهور، ومات أبوه قبل ولادته.","rules":["أرضعته حليمة السعدية في بادية بني سعد، وفيها كانت حادثة شق الصدر.","ماتت أمه آمنة وهو ابن ست سنين، فكفله جده عبد المطلب، ثم عمه أبو طالب.","رعى الغنم، وسافر للتجارة إلى الشام، وعُرف بالصادق الأمين.","تزوج خديجة رضي الله عنها وهو ابن خمس وعشرين سنة."],"ex":[["﴿ألم يجدك يتيماً فآوى﴾","الضحى: ٦."]],"q":[["من كفل النبي ﷺ بعد جده:",["أبو لهب","أبو طالب","العباس"],1,""]],"r":[["ibnhisham:1","السيرة النبوية","ذكر سرد النسب الزكي من محمد صلى الله عليه وآله وسلم، إلى آدم عليه السل"],["ibnhisham:226","السيرة النبوية","رأى ابن إسحاق مولده صلى الله عليه وسلم"],["zad:8","زاد المعاد في هدي خير العباد","فصل في نسبه صلى الله عليه وسلم"]],"s":[]},{"id":"bitha","t":"البعثة ونزول الوحي","idea":"كان النبي ﷺ يتعبّد في غار حراء، فجاءه جبريل وهو ابن أربعين سنة فقال: اقرأ، فنزلت أول آيات سورة العلق، فرجع إلى خديجة يرجف فؤاده، فطمأنته، وذهبت به إلى ورقة بن نوفل.","rules":["أول من آمن: خديجة من النساء، وأبو بكر من الرجال الأحرار، وعلي من الصبيان، وزيد بن حارثة من الموالي.","قالت خديجة: كلا والله ما يخزيك الله أبداً، إنك لتصل الرحم وتحمل الكلّ..."],"ex":[["«ما أنا بقارئ»","من حديث بدء الوحي في صحيح البخاري."]],"q":[["أول ما نزل من القرآن:",["اقرأ","المدثر"],0,""],["عمر النبي ﷺ عند البعثة:",["ثلاثون","أربعون"],1,""]],"r":[["ibnhisham:326","السيرة النبوية","مبعث النبي صلى الله عليه وعلى آله وسلم تسليما"],["zad:12","زاد المعاد في هدي خير العباد","فصل في مبعثه صلى الله عليه وسلم وأول ما نزل عليه"]],"s":[]},{"id":"dawa","t":"الدعوة سراً ثم جهراً","idea":"بقيت الدعوة سرية نحو ثلاث سنين، ثم أمر الله بالجهر: ﴿فاصدع بما تؤمر﴾، فصعد النبي ﷺ على الصفا ونادى قريشاً، فاشتد الأذى على المسلمين.","rules":["عُذّب المستضعفون: بلال، وآل ياسر، وخبّاب، وغيرهم؛ وسمية أول شهيدة في الإسلام.","كانت دار الأرقم بن أبي الأرقم مركز الدعوة السرية.","عرضت قريش على النبي ﷺ المال والملك فرفض."],"ex":[["﴿وأنذر عشيرتك الأقربين﴾","بداية الجهر بالدعوة."]],"q":[["أول شهيدة في الإسلام:",["خديجة","سمية"],1,""]],"r":[["ibnhisham:420","السيرة النبوية","عبد الله بن مسعود وما ناله من قريش في سبيل جهره بالقرآن"],["ibnhisham:394","السيرة النبوية","إيقاع حمزة بأبي جهل وإسلامه"]],"s":[]},{"id":"habasha","t":"الهجرة إلى الحبشة","idea":"لما اشتد الأذى أذن النبي ﷺ لأصحابه بالهجرة إلى الحبشة، لأن فيها ملكاً لا يُظلم عنده أحد: النجاشي. فهاجروا مرتين، وتكلم جعفر بن أبي طالب أمام النجاشي فقرأ صدر سورة مريم فبكى.","rules":["كانت الهجرة الأولى في السنة الخامسة من البعثة.","أرسلت قريش عمرو بن العاص لاستردادهم، فرفض النجاشي تسليمهم.","أسلم النجاشي، وصلى عليه النبي ﷺ صلاة الغائب لما مات."],"ex":[["«إن بأرض الحبشة ملكاً لا يُظلم أحد عنده»","ذكره ابن إسحاق."]],"q":[["من تكلم أمام النجاشي:",["جعفر بن أبي طالب","عثمان بن عفان"],0,""]],"r":[["ibnhisham:434","السيرة النبوية","من هاجروا الهجرة الأولى إلى الحبشة"]],"s":[]},{"id":"huzn","t":"الحصار وعام الحزن والطائف","idea":"حاصرت قريش بني هاشم في شعب أبي طالب ثلاث سنين، ثم مات أبو طالب وخديجة في عام واحد فسُمّي عام الحزن، ثم خرج النبي ﷺ إلى الطائف يدعو أهلها فردّوه وأغروا به سفهاءهم.","rules":["عرض عليه ملك الجبال أن يطبق عليهم الأخشبين فقال: «بل أرجو أن يخرج الله من أصلابهم من يعبد الله وحده».","في طريق العودة أسلم نفر من الجن."],"ex":[["«بل أرجو أن يخرج الله من أصلابهم من يعبد الله»","متفق عليه: من أعظم صور الرحمة."]],"q":[["سُمّي عام الحزن لوفاة:",["حمزة وجعفر","أبي طالب وخديجة"],1,""]],"r":[["ibnhisham:510","السيرة النبوية","بلاء هشام بن عمرو في نقض الصحيفة"],["zad:332","زاد المعاد في هدي خير العباد","فصل في موت أبي طالب وموت خديجة والخروج إلى الطائف"]],"s":[]},{"id":"isra","t":"الإسراء والمعراج","idea":"أُسري بالنبي ﷺ ليلاً من المسجد الحرام إلى المسجد الأقصى على البراق، فصلى بالأنبياء إماماً، ثم عُرج به إلى السماوات العلا، وفُرضت عليه الصلوات الخمس.","rules":["فُرضت الصلاة خمسين ثم خُففت إلى خمس في العمل وخمسين في الأجر.","صدّقه أبو بكر فسُمّي الصدّيق.","كان قبل الهجرة، واختُلف في تحديد سنته."],"ex":[["﴿سبحان الذي أسرى بعبده ليلاً من المسجد الحرام إلى المسجد الأقصى﴾","الإسراء: ١."]],"q":[["فُرضت الصلاة في:",["المدينة","ليلة المعراج"],1,""]],"r":[["ibnhisham:547","السيرة النبوية","ذكر الإسراء والمعراج"],["zad:333","زاد المعاد في هدي خير العباد","فصل في الإسراء والمعراج"]],"s":[]},{"id":"aqaba","t":"بيعتا العقبة","idea":"كان النبي ﷺ يعرض نفسه على القبائل في المواسم، فآمن نفر من الأنصار من المدينة، فكانت بيعة العقبة الأولى (١٢ رجلاً)، ثم الثانية (٧٠ رجلاً وامرأتان) على النصرة، فكانت تمهيداً للهجرة.","rules":["أرسل النبي ﷺ معهم مصعب بن عمير يعلمهم القرآن، فأسلم على يديه سعد بن معاذ وأسيد بن حضير."],"ex":[["مصعب بن عمير","أول سفير في الإسلام."]],"q":[["أول سفير في الإسلام:",["مصعب بن عمير","معاذ بن جبل"],0,""]],"r":[["ibnhisham:600","السيرة النبوية","العقبة الأولى ومصعب بن عمير"],["ibnhisham:614","السيرة النبوية","مصعب بن عمير والعقبة الثانية"]],"s":[]},{"id":"hijra","t":"الهجرة إلى المدينة","idea":"تآمرت قريش على قتل النبي ﷺ، فخرج مع أبي بكر وبات علي في فراشه، واختبآ في غار ثور ثلاثاً، ثم سارا إلى المدينة، ونزل بقباء فبنى أول مسجد، ثم دخل المدينة.","rules":["﴿ثاني اثنين إذ هما في الغار إذ يقول لصاحبه لا تحزن إن الله معنا﴾.","جعل عمر بن الخطاب الهجرة بداية التاريخ الإسلامي.","كان الدليل عبد الله بن أريقط، وأسماء بنت أبي بكر ذات النطاقين تحمل الطعام."],"ex":[["﴿إلا تنصروه فقد نصره الله إذ أخرجه الذين كفروا ثاني اثنين﴾","التوبة: ٤٠."]],"q":[["أول مسجد بُني في الإسلام:",["المسجد النبوي","مسجد قباء"],1,""]],"r":[["ibnhisham:681","السيرة النبوية","طمع أبي بكر في أن يكون صاحب النبي في الهجرة، وما أعد لذلك"],["ibnhisham:696","السيرة النبوية","قدومه صلى الله عليه وسلم قباء"]],"s":[]},{"id":"madina","t":"بناء المجتمع في المدينة","idea":"أسس النبي ﷺ المجتمع المسلم على ثلاث دعائم: بناء المسجد النبوي، والمؤاخاة بين المهاجرين والأنصار، وكتابة الوثيقة التي نظّمت العلاقة مع اليهود وغيرهم.","rules":["آخى بين عبد الرحمن بن عوف وسعد بن الربيع، فعرض سعد عليه نصف ماله، فقال: دلّني على السوق.","شُرع الأذان، وحُوّلت القبلة إلى الكعبة في السنة الثانية."],"ex":[["﴿ويؤثرون على أنفسهم ولو كان بهم خصاصة﴾","في الأنصار."]],"q":[["من قال «دلّني على السوق»:",["عبد الرحمن بن عوف","أبو هريرة"],0,""]],"r":[["ibnhisham:718","السيرة النبوية","من آخى بينهم صلى الله عليه وسلم"],["ibnhisham:707","السيرة النبوية","ارتجاز علي بن أبي طالب في بناء المسجد"],["zad:343","زاد المعاد في هدي خير العباد","فصل في المؤاخاة بين المهاجرين والأنصار"]],"s":[]},{"id":"badr","t":"غزوة بدر الكبرى","idea":"في رمضان من السنة الثانية للهجرة، خرج المسلمون (٣١٣ تقريباً) لعير قريش، فنجت العير، والتقوا بجيش قريش (نحو ألف) عند بدر، فنصر الله المؤمنين نصراً عظيماً، وسُمّي يوم الفرقان.","rules":["استشار النبي ﷺ أصحابه، فقال سعد بن معاذ: لو استعرضت بنا هذا البحر لخضناه معك.","قُتل من المشركين سبعون منهم أبو جهل، وأُسر سبعون.","أمد الله المسلمين بالملائكة."],"ex":[["﴿ولقد نصركم الله ببدر وأنتم أذلة﴾","آل عمران: ١٢٣."]],"q":[["كانت غزوة بدر في شهر:",["شوال","رمضان"],1,""]],"r":[["ibnhisham:912","السيرة النبوية","طريق المسلمين إلى بدر"],["zad:390","زاد المعاد في هدي خير العباد","فصل في بدء القتال يوم بدر بالمبارزة"]],"s":[]},{"id":"uhud","t":"غزوة أحد","idea":"في شوال من السنة الثالثة جاءت قريش للثأر، فكان النصر للمسلمين أولاً، ثم خالف أكثر الرماة أمر النبي ﷺ فنزلوا عن الجبل، فالتفّ خالد بن الوليد (قبل إسلامه) من خلفهم، فاستُشهد سبعون منهم حمزة رضي الله عنه.","rules":["الدرس الأكبر: خطر مخالفة أمر النبي ﷺ والطمع في الدنيا.","شُجّ وجه النبي ﷺ وكُسرت رباعيته."],"ex":[["﴿منكم من يريد الدنيا ومنكم من يريد الآخرة﴾","آل عمران: ١٥٢."]],"q":[["سبب الهزيمة بعد النصر في أحد:",["قلة العدد","مخالفة الرماة لأمر النبي ﷺ"],1,""]],"r":[["ibnhisham:1191","السيرة النبوية","المدة بين قدوم الرسول بحران وغزوة أحد"],["zad:397","زاد المعاد في هدي خير العباد","أحداث غزوة أحد (1)"]],"s":[]},{"id":"khandaq","t":"غزوة الأحزاب (الخندق)","idea":"في السنة الخامسة تحزّبت قريش وغطفان واليهود في نحو عشرة آلاف، فحفر المسلمون الخندق بمشورة سلمان الفارسي، وحاصرهم الأحزاب شهراً، ثم أرسل الله عليهم ريحاً وجنوداً فرحلوا.","rules":["نقض بنو قريظة عهدهم في أشد الأوقات.","قال النبي ﷺ بعدها: «الآن نغزوهم ولا يغزوننا»."],"ex":[["﴿فأرسلنا عليهم ريحاً وجنوداً لم تروها﴾","الأحزاب: ٩."]],"q":[["من أشار بحفر الخندق:",["سلمان الفارسي","أبو بكر"],0,""]],"r":[["ibnhisham:1456","السيرة النبوية","سلمان وإشارته بحفر الخندق"],["zad:419","زاد المعاد في هدي خير العباد","سبب غزوة الخندق"]],"s":[]},{"id":"hudaybiya","t":"صلح الحديبية","idea":"في السنة السادسة خرج النبي ﷺ معتمراً، فمنعته قريش، فكانت بيعة الرضوان، ثم الصلح: هدنة عشر سنين، ورجوع المسلمين ذلك العام. وسمّاه الله فتحاً مبيناً.","rules":["ظاهر الشروط فيه إجحاف، لكنه كان سبب انتشار الإسلام، فدخل فيه في سنتين أكثر ممن دخل قبل ذلك.","بعده راسل النبي ﷺ الملوك يدعوهم إلى الإسلام."],"ex":[["﴿لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة﴾","الفتح: ١٨."]],"q":[["مدة الهدنة في صلح الحديبية:",["سنة","عشر سنين"],1,""]],"r":[["zad:425","زاد المعاد في هدي خير العباد","عام الحديبية"],["zad:427","زاد المعاد في هدي خير العباد","فصل في ما جرى عليه صلح الحديبية"]],"s":[]},{"id":"fath","t":"فتح مكة","idea":"نقضت قريش الصلح بإعانة بني بكر على خزاعة حلفاء النبي ﷺ، فسار إليها في رمضان من السنة الثامنة بعشرة آلاف، فدخلها فاتحاً متواضعاً، وحطّم الأصنام، وعفا عن أهلها: «اذهبوا فأنتم الطلقاء».","rules":["دخل مكة خافضاً رأسه تواضعاً لله.","«من دخل دار أبي سفيان فهو آمن، ومن أغلق بابه فهو آمن».","بعدها غزوة حنين والطائف، وفي السنة التاسعة تبوك وعام الوفود."],"ex":[["﴿وقل جاء الحق وزهق الباطل﴾","كان يرددها وهو يحطم الأصنام."]],"q":[["فُتحت مكة في السنة:",["السادسة","الثامنة"],1,""]],"r":[["ibnhisham:1629","السيرة النبوية","بشرى فتح مكة وتعجل بعض المسلمين"],["zad:898","زاد المعاد في هدي خير العباد","فصل في حكمه صلى الله عليه وسلم في فتح مكة"]],"s":[]},{"id":"wafat","t":"حجة الوداع والوفاة","idea":"حج النبي ﷺ في السنة العاشرة حجته الوحيدة، وخطب خطبته الجامعة في عرفة، ونزل: ﴿اليوم أكملت لكم دينكم﴾. ثم مرض وتوفي يوم الاثنين في ربيع الأول من السنة الحادية عشرة، وعمره ثلاث وستون سنة.","rules":["من خطبته: «إن دماءكم وأموالكم حرام عليكم كحرمة يومكم هذا...».","قال أبو بكر: من كان يعبد محمداً فإن محمداً قد مات، ومن كان يعبد الله فإن الله حي لا يموت.","دُفن في حجرة عائشة رضي الله عنها حيث قُبض."],"ex":[["﴿اليوم أكملت لكم دينكم وأتممت عليكم نعمتي﴾","المائدة: ٣، نزلت يوم عرفة."]],"q":[["عمر النبي ﷺ عند وفاته:",["ستون","ثلاث وستون"],1,""]],"r":[["ibnhisham:2052","السيرة النبوية","خطبة الرسول في حجة الوداع"],["zad:160","زاد المعاد في هدي خير العباد","فصل في سياق هديه صلى الله عليه وسلم في حجته"],["ibnhisham:2117","السيرة النبوية","بدء الشكوى"]],"s":[]}]},"ibadat":{"ic":"🧎","t":"فقه العبادات المبسّط","d":"الطهارة والصلاة والزكاة والصيام والحج خطوة بخطوة، مع ذكر الخلاف المعتبر بين المذاهب وأدلته، من «بداية المجتهد» و«المغني» و«بلوغ المرام» ومتون المذاهب.","lessons":[{"id":"miyah","t":"المياه والنجاسات","idea":"الماء الذي يُتطهر به هو الماء الطهور الباقي على أصل خلقته: ماء المطر والبحر والآبار والأنهار. فإن تغيّر بنجاسة (لونه أو طعمه أو ريحه) صار نجساً بالإجماع.","rules":["البحر: «هو الطهور ماؤه الحل ميتته».","النجاسات المتفق عليها: البول والغائط من الآدمي، والدم المسفوح، والميتة (غير السمك والجراد)، ولحم الخنزير.","تطهير النجاسة بإزالتها بالماء حتى تزول عينها، ونجاسة الكلب تُغسل سبعاً أولاهن بالتراب.","المذاهب في الماء القليل إذا وقعت فيه نجاسة ولم يتغير: الجمهور (الحنفية والشافعية والحنابلة) ينجس إن كان دون القلتين، والمالكية: لا ينجس إلا بالتغير."],"ex":[["«إن الماء طهور لا ينجسه شيء»","رواه أبو داود والترمذي، وهو حجة المالكية."]],"q":[["الماء إذا تغيّر بنجاسة:",["طهور","نجس بالإجماع"],1,""]],"r":[["bulugh:1","بلوغ المرام من أدلة الأحكام","كتاب الطهارة"],["bidayat:6","بداية المجتهد ونهاية المقتصد","الباب الثالث في المياه (1)"],["abushuja:2","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الطهارة — …المياه التي يجوز التطهير بها سبع مي…"]],"s":[]},{"id":"wudu","t":"الوضوء: فرائضه وسننه ونواقضه","idea":"الوضوء شرط لصحة الصلاة. وفرائضه الأربعة المذكورة في الآية متفق عليها: غسل الوجه، واليدين إلى المرفقين، ومسح الرأس، وغسل الرجلين إلى الكعبين.","rules":["زاد الشافعية والحنابلة: النية والترتيب، وزاد الحنابلة الموالاة، والمضمضة والاستنشاق داخلان في الوجه عندهم.","زاد المالكية: النية، والدلك، والموالاة، ومسح جميع الرأس.","الحنفية: الفرائض أربعة فقط، والنية سنة.","النواقض المتفق عليها: الخارج من السبيلين، وزوال العقل بنوم مستغرق أو إغماء.","ومن المختلف فيه: مس الذكر، ولمس المرأة، وأكل لحم الإبل (ينقض عند الحنابلة للحديث الصحيح)."],"ex":[["﴿يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برؤوسكم وأرجلكم إلى الكعبين﴾","المائدة: ٦."]],"q":[["الفرائض المتفق عليها في الوضوء:",["اثنتان","أربع","سبع"],1,""],["أكل لحم الإبل ينقض الوضوء عند:",["الحنابلة","الحنفية"],0,""]],"r":[["bulugh:40","بلوغ المرام من أدلة الأحكام","كتاب الطهارة — …نه ‏- ‏-في صفه الوضوء‏- قال: { ومسح ‏- صلي الله عل…"],["bidayat:2","بداية المجتهد ونهاية المقتصد","الباب الأول الدليل على وجوب الوضوء"],["umdat-fiqh:6","عمدة الفقه — الحنبلي","باب الوضوء"]],"s":[]},{"id":"ghusl","t":"الغسل والتيمم","idea":"يجب الغسل بخروج المني، والجماع، والحيض والنفاس، والموت. وصفته المجزئة: النية وتعميم البدن بالماء. والتيمم بدل عن الماء عند فقده أو العجز عن استعماله.","rules":["الغسل الكامل: يغسل يديه، ثم فرجه، ثم يتوضأ، ثم يفيض الماء على رأسه ثلاثاً، ثم على سائر جسده.","صفة التيمم: ينوي، ويضرب الصعيد الطاهر بيديه، ويمسح وجهه وكفيه.","التيمم يُبطله ما يُبطل الوضوء، ووجود الماء لمن تيمم لفقده."],"ex":[["﴿فلم تجدوا ماء فتيمموا صعيداً طيباً﴾","المائدة: ٦."]],"q":[["ممسوح التيمم:",["الوجه والكفان","الرأس والرجلان"],0,"لحديث عمار في الصحيحين."]],"r":[["bulugh:31","بلوغ المرام من أدلة الأحكام","كتاب الطهارة — …ا انظر الي اثر الغسل فيه } متفق عليه 1‏ .‏‏1 ‏- ص…"],["bulugh:158","بلوغ المرام من أدلة الأحكام","كتاب الطهارة — … عليه وسلم ‏-{ التيمم ضربتان ضربه للوجه, وضربه للي…"],["bidayat:17","بداية المجتهد ونهاية المقتصد","كتاب التيمم"]],"s":[]},{"id":"salat-shurut","t":"شروط الصلاة وأركانها","idea":"الصلاة عمود الدين. ولها شروط قبل الدخول فيها، وأركان لا تصح إلا بها، وواجبات وسنن.","rules":["الشروط: الإسلام، والعقل، والتمييز، ودخول الوقت، والطهارة من الحدث والنجس، وستر العورة، واستقبال القبلة، والنية.","الأركان: القيام مع القدرة، وتكبيرة الإحرام، والفاتحة، والركوع، والرفع منه، والسجود على الأعضاء السبعة، والجلوس بين السجدتين، والطمأنينة، والتشهد الأخير وجلوسه، والتسليم.","الحنفية لا يجعلون الفاتحة ركناً بل واجباً، والركن عندهم قراءة ما تيسر.","من ترك ركناً لم تصح الركعة حتى يأتي به."],"ex":[["«صلوا كما رأيتموني أصلي»","رواه البخاري."],["«لا صلاة لمن لم يقرأ بفاتحة الكتاب»","متفق عليه، وهو دليل الجمهور."]],"q":[["دخول الوقت بالنسبة للصلاة:",["شرط","ركن","سنة"],0,""],["الطمأنينة في الصلاة:",["سنة","ركن"],1,"لحديث المسيء صلاته."]],"r":[["bulugh:180","بلوغ المرام من أدلة الأحكام","كتاب الصلاة"],["bidayat:33","بداية المجتهد ونهاية المقتصد","الجملة الأولى في معرفة وجوب الصلاة — الصلاة تنقسم أولا وبالجملة إلى فر"],["zad-mustaqni:15","زاد المستقنع — الحنبلي","باب شروط الصلاة"]],"s":[]},{"id":"salat-sifa","t":"صفة الصلاة باختصار","idea":"صفة صلاة النبي ﷺ: يكبّر رافعاً يديه، ويضع اليمنى على اليسرى، ويستفتح، ويستعيذ، ويقرأ الفاتحة وما تيسر، ثم يركع ويرفع ويسجد ويجلس ويسجد، ثم يقوم للثانية، ويتشهد، ثم يسلّم.","rules":["دعاء الاستفتاح: «سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك».","في الركوع: سبحان ربي العظيم، وفي السجود: سبحان ربي الأعلى، وبين السجدتين: رب اغفر لي.","يرفع يديه عند التكبير، والركوع، والرفع منه، والقيام من التشهد الأول عند الشافعية والحنابلة، والحنفية لا يرفعون إلا في تكبيرة الإحرام."],"ex":[["حديث المسيء صلاته","متفق عليه: «ثم اركع حتى تطمئن راكعاً...»."]],"q":[["ما يقال في السجود:",["سبحان ربي العظيم","سبحان ربي الأعلى"],1,""]],"r":[["bulugh:180","بلوغ المرام من أدلة الأحكام","كتاب الصلاة"],["bidayat:101","بداية المجتهد ونهاية المقتصد","الفصل الأول في صفة صلاة الجنازة — …ه الجنازه فاما صفه الصلاه فانها يتعلق بها مسائل: ا…"]],"s":[]},{"id":"sahw","t":"سجود السهو","idea":"سجدتان يجبر بهما المصلي ما يقع في صلاته من خلل سهواً: بزيادة، أو نقص، أو شك.","rules":["من ترك واجباً كالتشهد الأول سهواً سجد للسهو.","من زاد ركعة سهواً سجد للسهو.","من شك في عدد الركعات بنى على اليقين (الأقل) ثم سجد.","موضعه: اختلف الفقهاء: قبل السلام عند الشافعية، وبعده عند الحنفية، وفرّق المالكية: للنقص قبله وللزيادة بعده، والحنابلة يتبعون ما ورد في كل حديث."],"ex":[["«إذا شك أحدكم في صلاته فلم يدر كم صلى... فليطرح الشك وليبن على ما استيقن»","رواه مسلم."]],"q":[["من شك هل صلى ثلاثاً أم أربعاً:",["يبني على الأكثر","يبني على الأقل ويسجد للسهو"],1,""]],"r":[["mughni:687","المغني","مسألة سجود السهو"],["bidayat:78","بداية المجتهد ونهاية المقتصد","الفصل الثاني في معرفة مواضع سجود السهو"]],"s":[]},{"id":"jamaa","t":"صلاة الجماعة والجمعة","idea":"صلاة الجماعة تفضل صلاة الفرد بسبع وعشرين درجة. والجمعة فرض عين على الرجل المسلم البالغ العاقل المقيم، وهي ركعتان تسبقهما خطبتان.","rules":["حكم الجماعة: واجبة عند الحنابلة، وسنة مؤكدة عند الحنفية والمالكية، وفرض كفاية على الصحيح عند الشافعية.","من آداب الجمعة: الغسل، والتطيب، والتبكير، والإنصات للخطبة، وقراءة سورة الكهف، والإكثار من الصلاة على النبي ﷺ.","«من قال لصاحبه يوم الجمعة: أنصت، والإمام يخطب فقد لغا» متفق عليه."],"ex":[["﴿يا أيها الذين آمنوا إذا نودي للصلاة من يوم الجمعة فاسعوا إلى ذكر الله﴾","الجمعة: ٩."]],"q":[["صلاة الجماعة تفضل صلاة الفرد بـ:",["عشر درجات","سبع وعشرين درجة"],1,""]],"r":[["bulugh:479","بلوغ المرام من أدلة الأحكام","كتاب الصلاة — … في احاديث فضل صلاه الجماعه، وقد تناولتها بالتفصيل…"],["bulugh:541","بلوغ المرام من أدلة الأحكام","كتاب الصلاة — …ن ادرك ركعه من صلاه الجمعه وغيرها فليضف اليها اخري…"],["bidayat:63","بداية المجتهد ونهاية المقتصد","الفصل الأول في وجوب الجمعة ومن تجب عليه"]],"s":[]},{"id":"safar","t":"صلاة المسافر والمريض","idea":"من رحمة الله أن خفف عن المسافر: فيقصر الصلاة الرباعية إلى ركعتين، ويجوز له الجمع بين الظهر والعصر، والمغرب والعشاء. والمريض يصلي على حسب استطاعته.","rules":["مسافة القصر عند الجمهور: أربعة بُرُد، وتقدّر بنحو ٨٠ كيلومتراً.","إذا نوى الإقامة أكثر من أربعة أيام أتمّ عند الجمهور، وعند الحنفية خمسة عشر يوماً.","القصر سنة مؤكدة عند الجمهور، وواجب عند الحنفية.","المريض: «صلِّ قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب» رواه البخاري."],"ex":[["﴿وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة﴾","النساء: ١٠١."]],"q":[["الصلاة التي لا تُقصر:",["العشاء","المغرب"],1,""]],"r":[["mughni:955","المغني","فصل قصد بلدا بعينه فوصله غير عازم على الإقامة به هل يقصر الصلاة"],["bidayat:67","بداية المجتهد ونهاية المقتصد","الفصل الأول في القصر"]],"s":[]},{"id":"janaiz","t":"أحكام الجنائز","idea":"تجهيز الميت فرض كفاية: تغسيله، وتكفينه، والصلاة عليه، ودفنه. ويُستحب تلقين المحتضر: لا إله إلا الله.","rules":["صلاة الجنازة: أربع تكبيرات: بعد الأولى الفاتحة، وبعد الثانية الصلاة على النبي ﷺ، وبعد الثالثة الدعاء للميت، وبعد الرابعة يسلّم.","الإسراع بالجنازة سنة، ومن تبعها حتى يُصلى عليها فله قيراط، وحتى تُدفن فله قيراطان.","التعزية سنة، ويحرم النياحة وشق الجيوب."],"ex":[["«لقنوا موتاكم لا إله إلا الله»","رواه مسلم."]],"q":[["عدد تكبيرات صلاة الجنازة:",["ثلاث","أربع"],1,""]],"r":[["bulugh:641","بلوغ المرام من أدلة الأحكام","كتاب الجنائز"],["bidayat:9","بداية المجتهد ونهاية المقتصد","الباب الخامس وهو معرفة الأفعال التي تشترط هذه الطهارة في فعلها — …علي الصلاه علي الجنائز وعلي السجود، فمن ذهب الي اس…"]],"s":[]},{"id":"zakat","t":"الزكاة: النصاب والمقدار","idea":"الزكاة ركن من أركان الإسلام، تجب في المال إذا بلغ النصاب وحال عليه الحول. وفي النقدين وعروض التجارة ربع العشر (٢٫٥٪).","rules":["نصاب الذهب: عشرون مثقالاً (نحو ٨٥ جراماً)، ونصاب الفضة: مائتا درهم (نحو ٥٩٥ جراماً)، والنقود الورقية تُقدّر بأحدهما.","عروض التجارة: تُقوّم عند تمام الحول بسعر السوق ويخرج ٢٫٥٪.","الزروع والثمار: العشر فيما سُقي بلا كلفة، ونصف العشر فيما سُقي بكلفة، ونصابها خمسة أوسق.","مصارفها ثمانية في آية التوبة: ﴿إنما الصدقات للفقراء والمساكين...﴾.","زكاة حلي المرأة المعد للاستعمال: واجبة عند الحنفية، ولا تجب عند الجمهور."],"ex":[["﴿خذ من أموالهم صدقة تطهرهم وتزكيهم بها﴾","التوبة: ١٠٣."]],"q":[["مقدار زكاة النقود:",["٥٪","٢٫٥٪","١٠٪"],1,""],["مصارف الزكاة:",["خمسة","ثمانية"],1,""]],"r":[["bulugh:707","بلوغ المرام من أدلة الأحكام","كتاب الزكاة"],["bidayat:107","بداية المجتهد ونهاية المقتصد","الجملة الأولى في معرفة من تجب عليه الزكاة — بسم الله الرحمن الرحيم كتا"],["mughni:1280","المغني","فصل أنكر وجوب الزكاة جهلا به — قال أبو محمد بن قتيبة: الزكاة من الزكاء"]],"s":[]},{"id":"fitr","t":"زكاة الفطر","idea":"زكاة الفطر صاع من طعام عن كل مسلم: الصغير والكبير، والذكر والأنثى، يخرجها عنه وعمن تلزمه نفقته، طهرة للصائم وطعمة للمساكين.","rules":["وقتها: قبل صلاة العيد، ويجوز قبل العيد بيوم أو يومين.","الصاع النبوي يقارب ٢٫٥–٣ كيلوجرامات من الأرز أو القمح.","إخراجها نقداً: يجيزه الحنفية، والجمهور على إخراجها طعاماً كما في الحديث."],"ex":[["«فرض رسول الله ﷺ زكاة الفطر صاعاً من تمر أو صاعاً من شعير...»","متفق عليه من حديث ابن عمر."]],"q":[["آخر وقت إخراج زكاة الفطر المستحب:",["قبل صلاة العيد","آخر رمضان بأسبوع"],0,""]],"r":[["bulugh:736","بلوغ المرام من أدلة الأحكام","كتاب الزكاة — …ه وسلم ان نخرج صدقه الفطر عن كل صغير وكبير، حر او …"],["bidayat:119","بداية المجتهد ونهاية المقتصد","الفصل الأول في معرفة حكم زكاة الفطر"]],"s":[]},{"id":"siyam","t":"الصيام: أحكامه ومفطراته","idea":"صيام رمضان ركن من أركان الإسلام، وهو الإمساك عن المفطرات من طلوع الفجر الصادق إلى غروب الشمس بنية.","rules":["المفطرات: الأكل والشرب عمداً، والجماع (وفيه الكفارة المغلظة)، وتعمّد القيء، وخروج دم الحيض والنفاس.","من أكل أو شرب ناسياً فليتم صومه، فإنما أطعمه الله وسقاه.","الحجامة تفطر عند الحنابلة، ولا تفطر عند الجمهور.","يباح الفطر للمريض والمسافر ويقضيان، والكبير العاجز يطعم عن كل يوم مسكيناً.","النية من الليل شرط في صوم الفرض عند الجمهور."],"ex":[["﴿يا أيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون﴾","البقرة: ١٨٣."]],"q":[["من أكل ناسياً وهو صائم:",["يفطر ويقضي","يتم صومه ولا شيء عليه"],1,""]],"r":[["bulugh:758","بلوغ المرام من أدلة الأحكام","كتاب الصيام"],["bidayat:124","بداية المجتهد ونهاية المقتصد","القسم الأول من الصوم المفروض الجملة الأولى أنواع الصيام الواجب — وهذا "],["zad-mustaqni:35","زاد المستقنع — الحنبلي","مدخل — ... كتاب الصيام يجب صوم رمضان برؤية هلال"]],"s":[]},{"id":"hajj","t":"الحج والعمرة","idea":"الحج ركن من أركان الإسلام، يجب مرة في العمر على المسلم المستطيع. وله أركان لا يصح إلا بها، وواجبات تُجبر بدم.","rules":["أركان الحج عند الجمهور: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة.","من الواجبات: الإحرام من الميقات، والمبيت بمزدلفة ومنى، ورمي الجمار، والحلق أو التقصير، وطواف الوداع.","أنواع النسك: التمتع، والقران، والإفراد.","العمرة: إحرام، وطواف، وسعي، وحلق أو تقصير.","«الحج عرفة» رواه أصحاب السنن."],"ex":[["﴿ولله على الناس حج البيت من استطاع إليه سبيلاً﴾","آل عمران: ٩٧."]],"q":[["أعظم أركان الحج:",["رمي الجمار","الوقوف بعرفة"],1,""],["ترك واجب من واجبات الحج يُجبر بـ:",["دم","لا شيء"],0,""]],"r":[["bulugh:816","بلوغ المرام من أدلة الأحكام","كتاب الحج"],["bidayat:136","بداية المجتهد ونهاية المقتصد","الجنس الأول معرفة وجوب الحج وشروطه — [كتاب الحج] والنظر في هذا الكتاب "],["umdat-fiqh:45","عمدة الفقه — الحنبلي","مدخل — ... كتاب الحج والعمرة يجب الحج والعمرة م"]],"s":[]}]},"faraid":{"ic":"🧮","t":"علم الفرائض (المواريث) خطوة بخطوة","d":"كيف تُقسم التركة؟ أصحاب الفروض والعصبات والحجب والعول، ثم جرّب بنفسك في «حاسبة المواريث». من «بداية المجتهد» و«المغني» و«متن أبي شجاع».","lessons":[{"id":"muqaddima","t":"مقدمة: التركة وأركان الإرث","idea":"قبل قسمة التركة تُخرج منها بالترتيب: تجهيز الميت، ثم ديونه، ثم وصيته في حدود الثلث لغير وارث، ثم يُقسم الباقي على الورثة.","rules":["أركان الإرث: المورِّث (الميت)، والوارث (الحي)، والحق الموروث.","أسبابه: النكاح، والنسب (القرابة)، والولاء.","موانعه: القتل، واختلاف الدين، والرق.","«لا يرث المسلم الكافر ولا الكافر المسلم» متفق عليه."],"ex":[["«ألحقوا الفرائض بأهلها، فما بقي فلأولى رجل ذكر»","متفق عليه: أصل في الفروض والتعصيب."]],"q":[["ما يُقدم على قسمة التركة:",["الوصية ثم الدين","تجهيز الميت ثم الدين ثم الوصية"],1,""],["من موانع الإرث:",["القتل","الفقر"],0,""]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"nisf","t":"أصحاب النصف والربع والثمن","idea":"الفروض المقدّرة في القرآن ستة: النصف، والربع، والثمن، والثلثان، والثلث، والسدس. وهذا الدرس للثلاثة الأولى.","rules":["النصف لخمسة: الزوج إذا لم يكن للميتة فرع وارث، والبنت المنفردة، وبنت الابن المنفردة إذا لم تكن بنت، والأخت الشقيقة المنفردة، والأخت لأب المنفردة (بشروطهن).","الربع: للزوج إذا كان للميتة فرع وارث، وللزوجة أو الزوجات إذا لم يكن للميت فرع وارث.","الثمن: للزوجة أو الزوجات إذا كان للميت فرع وارث."],"ex":[["﴿ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد﴾","النساء: ١٢."]],"q":[["ماتت امرأة عن زوج وابن: للزوج:",["النصف","الربع"],1,"لوجود الفرع الوارث."],["مات رجل عن زوجتين وبنت: للزوجتين معاً:",["الثمن","الربع لكل واحدة"],0,"يشتركن في الثمن."]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"thuluth","t":"أصحاب الثلثين والثلث والسدس","idea":"الثلثان للاثنتين فأكثر ممن فرضه النصف من الإناث. والثلث للأم وللإخوة لأم. والسدس لسبعة.","rules":["الثلثان: للبنتين فأكثر، ولبنتي الابن فأكثر، وللأختين الشقيقتين فأكثر، وللأختين لأب فأكثر (عند عدم المعصّب).","الثلث: للأم إذا لم يكن للميت فرع وارث ولا جمع من الإخوة، وللإخوة لأم اثنين فأكثر يستوي ذكرهم وأنثاهم.","في «العُمَريّتين» (زوج أو زوجة مع أب وأم): للأم ثلث الباقي بعد فرض الزوج.","السدس: للأب والجد مع الفرع الوارث، وللأم مع الفرع الوارث أو جمع الإخوة، وللجدة، ولبنت الابن مع البنت، وللأخت لأب مع الشقيقة، وللواحد من ولد الأم."],"ex":[["﴿فإن كن نساء فوق اثنتين فلهن ثلثا ما ترك﴾","النساء: ١١."]],"q":[["مات عن أم وأب وابن: للأم:",["الثلث","السدس"],1,"لوجود الفرع الوارث."],["الإخوة لأم إذا كانوا اثنين فأكثر:",["يأخذون الثلث يستوي فيه الذكر والأنثى","للذكر مثل حظ الأنثيين"],0,""]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"tasib","t":"التعصيب","idea":"العاصب: من يأخذ ما بقي بعد أصحاب الفروض، أو كل المال إذا انفرد. وأقربهم بالترتيب: البنوة (الابن وابنه)، ثم الأبوة (الأب والجد)، ثم الأخوة، ثم العمومة.","rules":["العصبة بالنفس: الذكور من الأقارب الذين لا تتوسط بينهم وبين الميت أنثى.","العصبة بالغير: البنت مع الابن، وبنت الابن مع ابن الابن، والأخت مع أخيها: للذكر مثل حظ الأنثيين.","العصبة مع الغير: الأخت الشقيقة أو لأب مع البنت أو بنت الابن."],"ex":[["﴿يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين﴾","النساء: ١١."]],"q":[["مات عن ابن وبنت وتركته ٣٠٠ ألف:",["للابن ٢٠٠ وللبنت ١٠٠","لكل واحد ١٥٠"],0,"للذكر مثل حظ الأنثيين."]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"hajb","t":"الحجب","idea":"الحجب: منع وارث من الإرث كله أو بعضه لوجود من هو أقرب منه. فحجب الحرمان يمنعه كلياً، وحجب النقصان يُنقص نصيبه.","rules":["لا يُحجب حجب حرمان ستة: الأب، والأم، والابن، والبنت، والزوج، والزوجة.","الابن يحجب الإخوة جميعاً وابن الابن، والأب يحجب الجد والإخوة.","حجب النقصان: كانتقال الزوج من النصف إلى الربع لوجود الولد."],"ex":[["مات عن ابن وأخ شقيق","الأخ محجوب بالابن، فالمال كله للابن."]],"q":[["من لا يُحجب حجب حرمان:",["الجد","الأم"],1,""],["الأب مع الإخوة:",["يحجبهم","يشاركهم"],0,""]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"awl","t":"العول والرد","idea":"العول: إذا زادت الفروض على أصل المسألة، نقصت أنصبة الجميع بنسبة واحدة. والرد: إذا بقي شيء بعد الفروض ولا عاصب، رُدّ على أصحاب الفروض غير الزوجين عند الجمهور.","rules":["أول من حكم بالعول عمر بن الخطاب رضي الله عنه بمشورة الصحابة.","مثال العول: زوج وأختان شقيقتان: للزوج النصف (٣ من ٦)، وللأختين الثلثان (٤ من ٦)، فالمجموع ٧، فتعول المسألة من ٦ إلى ٧."],"ex":[["زوج وأختان شقيقتان","تعول المسألة من ستة إلى سبعة."]],"q":[["العول يعني:",["زيادة السهام على أصل المسألة","بقاء شيء من التركة"],0,""]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]},{"id":"tatbiq","t":"تطبيق عملي مع الحاسبة","idea":"لحل أي مسألة: ١) اكتب الورثة. ٢) أخرج المحجوبين. ٣) أعط أصحاب الفروض فروضهم. ٤) أعط الباقي للعاصب. ٥) صحّح المسألة. ثم جرّب «حاسبة المواريث» في التطبيق لتتأكد.","rules":["مثال: مات رجل عن زوجة وأم وابن وبنت: للزوجة الثمن (لوجود الفرع)، وللأم السدس (لوجود الفرع)، والباقي للابن والبنت للذكر مثل حظ الأنثيين.","أصل المسألة ٢٤: للزوجة ٣، وللأم ٤، والباقي ١٧ يُقسم أثلاثاً، فتصح من ٧٢.","تنبيه: المسائل المعقدة والوقائع الحقيقية تُعرض على أهل الاختصاص أو المحكمة الشرعية."],"ex":[["#/mirath","افتح «حاسبة المواريث» من قسم علوم الشريعة."]],"q":[["زوجة وأم وابن: للأم:",["الثلث","السدس"],1,""]],"r":[["bidayat:396","بداية المجتهد ونهاية المقتصد","كتاب الفرائض"],["mughni:4001","المغني","كتاب الفرائض"],["abushuja:8","متن أبي شجاع (الغاية والتقريب) — الشافعي","كتاب الفرائض والوصايا"]],"s":[]}]},"adab":{"ic":"🌸","t":"الآداب الإسلامية","d":"آداب يومية للأسرة والأطفال من «رياض الصالحين» و«الأدب المفرد»: الطعام، والسلام، والمجلس، والطريق، والجار، والنوم، والزيارة.","lessons":[{"id":"taam","t":"آداب الطعام والشراب","idea":"الطعام نعمة، ومن شكرها اتباع السنة في تناوله.","rules":["التسمية في أوله: «يا غلام، سمِّ الله، وكل بيمينك، وكل مما يليك» متفق عليه.","إن نسي التسمية قال: بسم الله أوله وآخره.","الأكل والشرب باليمين، وعدم ذم الطعام: «ما عاب رسول الله ﷺ طعاماً قط، إن اشتهاه أكله وإلا تركه».","الحمد بعد الفراغ، والشرب جالساً على ثلاث دفعات."],"ex":[["«سمِّ الله، وكل بيمينك، وكل مما يليك»","متفق عليه."]],"q":[["إذا نسيت التسمية في أول الطعام تقول:",["بسم الله أوله وآخره","لا شيء"],0,""]],"r":[["riyad:48","رياض الصالحين","كتـــــاب أدب الطعام"]],"s":[]},{"id":"salam","t":"السلام والاستئذان","idea":"السلام تحية الإسلام، ونشره سبب للمحبة ودخول الجنة. والاستئذان أدب لحفظ البيوت والعورات.","rules":["«ألا أدلكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم» رواه مسلم.","يسلّم الصغير على الكبير، والمار على القاعد، والقليل على الكثير، والراكب على الماشي.","الاستئذان ثلاثاً، فإن أُذن لك وإلا فارجع، ولا تقف مقابل الباب.","رد السلام واجب، وابتداؤه سنة."],"ex":[["﴿وإذا حُييتم بتحية فحيوا بأحسن منها أو ردوها﴾","النساء: ٨٦."]],"q":[["الاستئذان:",["مرة واحدة","ثلاث مرات"],1,""],["حكم رد السلام:",["واجب","سنة"],0,""]],"r":[["riyad:165","رياض الصالحين","كتاب السلام"],["adab:967","الأدب المفرد","كتاب السَّلامِ"]],"s":[]},{"id":"majlis","t":"آداب المجلس والحديث","idea":"المجالس بالأمانة، وحسن الحديث من كمال الإيمان.","rules":["«من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت» متفق عليه.","لا يقيم الرجل الرجل من مجلسه ثم يجلس فيه، ولكن تفسّحوا.","لا يتناجى اثنان دون الثالث فإن ذلك يحزنه.","كفارة المجلس: «سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك»."],"ex":[["﴿يا أيها الذين آمنوا إذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم﴾","المجادلة: ١١."]],"q":[["تناجي اثنين دون الثالث:",["جائز","منهي عنه"],1,""]],"r":[["riyad:1","رياض الصالحين","كتاب الأدب"]],"s":[]},{"id":"tariq","t":"آداب الطريق","idea":"للطريق حقوق ذكرها النبي ﷺ لمن جلس فيه أو مرّ به.","rules":["«فأعطوا الطريق حقه: غض البصر، وكف الأذى، ورد السلام، والأمر بالمعروف، والنهي عن المنكر» متفق عليه.","إماطة الأذى عن الطريق صدقة وشعبة من الإيمان.","ومن حقه في زماننا: احترام أنظمة السير، وعدم إيذاء المارة."],"ex":[["«إماطة الأذى عن الطريق صدقة»","متفق عليه."]],"q":[["من حق الطريق:",["غض البصر","رفع الصوت"],0,""]],"r":[["riyad:1","رياض الصالحين","كتاب الأدب"]],"s":[]},{"id":"jar","t":"حق الجار","idea":"أوصى الإسلام بالجار وصية عظيمة حتى ظن النبي ﷺ أنه سيورّثه.","rules":["«ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه» متفق عليه.","«والله لا يؤمن... من لا يأمن جاره بوائقه» رواه البخاري.","من حقوقه: الإهداء إليه ولو بالقليل، وعيادته، وتهنئته، وتعزيته، وكف الأذى عنه."],"ex":[["«يا أبا ذر، إذا طبخت مرقة فأكثر ماءها وتعاهد جيرانك»","رواه مسلم."]],"q":[["من حقوق الجار:",["كف الأذى والإهداء إليه","لا حقوق له"],0,""]],"r":[["adab:101","الأدب المفرد","كتاب الْجَارِ"]],"s":[]},{"id":"nawm","t":"آداب النوم والاستيقاظ","idea":"النوم آية من آيات الله، ومن السنة فيه أذكار وآداب تحفظ المسلم.","rules":["النوم على طهارة، والاضطجاع على الشق الأيمن.","قراءة آية الكرسي والمعوّذات، وقول: «باسمك اللهم أموت وأحيا».","عند الاستيقاظ: «الحمد لله الذي أحيانا بعدما أماتنا وإليه النشور».","التبكير في النوم والاستيقاظ، و«بورك لأمتي في بكورها»."],"ex":[["«باسمك اللهم أموت وأحيا»","رواه البخاري."]],"q":[["السنة في النوم الاضطجاع على:",["الشق الأيمن","البطن"],0,""]],"r":[["riyad:134","رياض الصالحين","كتاب آداب النوم"],["adab:1208","الأدب المفرد","كتاب النوم والمبيت"]],"s":[]},{"id":"libas","t":"آداب اللباس والزينة","idea":"اللباس نعمة للستر والزينة، وله آداب.","rules":["التسمية عند اللبس، والبدء باليمين، والخلع بالشمال.","يحرم على الرجال لبس الحرير والذهب، ويحرم الإسبال على وجه الخيلاء.","لا يتشبه الرجال بالنساء ولا النساء بالرجال.","دعاء لبس الجديد: «اللهم لك الحمد أنت كسوتنيه...»."],"ex":[["﴿يا بني آدم قد أنزلنا عليكم لباساً يواري سوآتكم وريشاً ولباس التقوى ذلك خير﴾","الأعراف: ٢٦."]],"q":[["عند لبس الثوب يبدأ بـ:",["اليمين","الشمال"],0,""]],"r":[["riyad:99","رياض الصالحين","كتــــاب اللباس"]],"s":[]},{"id":"marid","t":"عيادة المريض والضيافة","idea":"عيادة المريض حق للمسلم على أخيه، وإكرام الضيف من الإيمان.","rules":["«حق المسلم على المسلم خمس: رد السلام، وعيادة المريض، واتباع الجنائز، وإجابة الدعوة، وتشميت العاطس» متفق عليه.","دعاء المريض: «لا بأس، طهور إن شاء الله».","«من كان يؤمن بالله واليوم الآخر فليكرم ضيفه»، والضيافة ثلاثة أيام.","تشميت العاطس: إذا حمد الله قيل له: يرحمك الله، فيقول: يهديكم الله ويصلح بالكم."],"ex":[["«لا بأس، طهور إن شاء الله»","رواه البخاري."]],"q":[["من حقوق المسلم على المسلم:",["عيادة المريض","إعطاؤه ماله"],0,""],["ماذا يقول من شُمّت؟",["يهديكم الله ويصلح بالكم","لا شيء"],0,""]],"r":[["riyad:215","رياض الصالحين","كتاب عيادة المريض وتشييع الميت والصلاة عليه وحضور دفنه"],["adab:520","الأدب المفرد","كتاب عيادة المرضى — …‏ عودوا المريض، واتبعوا الجنائز، تذكركم الا…"]],"s":[]},{"id":"walidayn","t":"بر الوالدين وصلة الرحم","idea":"بر الوالدين من أعظم القربات بعد التوحيد، وصلة الرحم سبب لسعة الرزق وطول العمر.","rules":["قُرن حق الوالدين بحق الله: ﴿وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحساناً﴾.","لا تقل لهما «أف»، وادعُ لهما في حياتهما وبعد موتهما.","«من أحب أن يبسط له في رزقه وينسأ له في أثره فليصل رحمه» متفق عليه.","وفي التطبيق قسم «زاد الوالدين» لتربية الأبناء."],"ex":[["﴿وقل رب ارحمهما كما ربياني صغيراً﴾","الإسراء: ٢٤."]],"q":[["من ثمرات صلة الرحم:",["البسط في الرزق","لا ثمرة لها"],0,""]],"r":[["riyad:395","رياض الصالحين","كتاب الفضائل — …ي‏؟‏ قال‏:‏ ‏\"‏بر الوالدين‏\"‏ قلت ثم اي‏؟‏ قال‏:‏ …"],["adab:1","الأدب المفرد","كتاب الْوَالِدَيْنِ — …ي‏؟‏ قال‏:‏ ثم بر الوالدين، قلت‏:‏ ثم اي‏؟‏ قال‏:‏…"]],"s":[]}]}}};
